const allLessons = D.codes.flatMap(c=>c.lessons.map(l=>({...l,code:c.id,codeName:c.name})));
const allCases = D.codes.flatMap(c=>c.cases.map((v,i)=>({...v,id:`${c.id}-case-${i}`,code:c.id})));
const ALL = Object.freeze({wages:'Wages',industrial:'Industrial Relations',security:'Social Security',osh:'Occupational Safety'});
const roles={hr:'HR Professional',employee:'Employee',employer:'Employer / Business',student:'Student / Learner',legal:'Legal / Compliance'};
