function icon(name,size=18){return `<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.learn}</svg>`}
function esc(s){return String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function att(s){return esc(s)}
function fmt(n){return new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(Number(n)||0)}
function cash(n){return '₹'+fmt(n)}
function num(v){return Number.isFinite(Number(v))?Number(v):0}
function short(s,n=122){const t=String(s||'');return t.length>n?t.slice(0,n-1)+'…':t}
function dateLabel(d){try{return new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}catch(e){return d}}
function codePill(id){return `<span class="pill" style="color:${C[id]?.color||'var(--teal)'}">${esc(ALL[id]||id)}</span>`}
function meter(v){return `<div class="meter"><span style="width:${Math.max(0,Math.min(100,v))}%"></span></div>`}
function notice(text){return `<div class="banner warn"><b>Important legal context</b><p>${esc(text)}</p></div>`}
function extlink(url,text){return `<a href="${att(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`}
const NAV=[
 {section:'WORKSPACE',items:[['home','Overview','home'],['learn','Learn the Codes','learn'],['academy','Learning Academy','academy'],['quiz','Quiz & Mock Tests','quiz'],['advisor','Legal Tutor','advisor']]},
 {section:'LEGAL REFERENCE',items:[['fullacts','Full Legal Texts','learn'],['visuals','Visual Explorer','chart'],['glossary','Legal Dictionary','glossary'],['compare','Old vs New Laws','compare'],['updates','Legal Updates','updates']]},
 {section:'PROFESSIONAL SUITE',items:[['compliance','Compliance Explorer','compliance'],['calculator','HR Calculators','calculator'],['planner','Action Planner','planner'],['documents','Document Reviewer','documents'],['reports','Reports & Insights','reports']]},
 {section:'PREFERENCES',items:[['settings','Settings','settings']]}
];
const defaultState=()=>({role:'hr',theme:'light',language:'en',completed:[],bookmarks:[],scores:[],checkmarks:[],flashcards:{},tasks:[],studyDays:[],fontScale:1.08,preferredState:'Bihar'});
let state=defaultState(),view={route:'home',code:'wages',lesson:null,query:'',filteredCode:'all',glossaryQuery:'',docResult:null,quiz:null,flashIdx:0,flashRevealed:false,flashFilter:'all',calculator:'wage',calcResults:null,tutorAnswer:null,tutorAsk:'',tutorMode:'offline',caseIdx:0,cert:false};
let appToken=window.AndroidBridge?'android-local':decodeURIComponent(window.location.hash.slice(1).trim());
let cloudBearer='';
let savedQueue=Promise.resolve();
const app=document.getElementById('app');
const modalRoot=document.getElementById('modal-root');
function roleTitle(){return roles[state.role]||roles.hr}
function completedFor(id){return C[id].lessons.filter(l=>state.completed.includes(l.id)).length}
function percentDone(){return Math.round(state.completed.length / allLessons.length *100)}
function mastery(code){const scores=state.scores.filter(s=>s.code===code || s.code==='all');return scores.length ? Math.round(scores.reduce((a,b)=>a+b.correct/b.total*100,0)/scores.length):0}
function addStudy(){let date=new Date().toLocaleDateString('en-CA');if(!state.studyDays.includes(date))state.studyDays.push(date)}
function markSaved(){const snapshot=JSON.stringify(state);if(window.AndroidBridge){AndroidBridge.saveState(snapshot);return} savedQueue=savedQueue.catch(()=>{}).then(()=>fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json','X-LCP-Token':appToken},body:snapshot})).then(r=>{if(!r.ok)throw Error('Save failed')}).catch(e=>console.warn('Progress save error',e))}
function toast(s){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=s;document.body.append(el);setTimeout(()=>el.remove(),2700)}
function go(route,code,lesson){view.route=route;view.code=code||view.code;view.lesson=lesson||null;view.calcResults=null;view.cert=false;window.scrollTo({top:0,behavior:'instant'});render()}
function renderSide(){return `<aside class="sidebar"><div class="brand"><img src="assets/logo.png" class="brand-img" alt="LabourCode Pro logo"><div><strong>LabourCode Pro</strong><small>PREMIUM ANDROID 1.0</small></div></div><nav aria-label="Main navigation">${NAV.map(g=>`<div><div class="nav-label">${g.section}</div>${g.items.map(([id,title,ico])=>`<button type="button" data-go="${id}" class="nav-item ${view.route===id?'active':''}" title="${title}" aria-label="${title}">${icon(ico)}<span>${title}</span>${id==='academy'?'<em>PRO</em>':''}</button>`).join('')}</div>`).join('')}</nav><div class="side-bottom"><small>YOUR LEARNING PROGRESS</small><div style="display:flex;justify-content:space-between;margin-top:8px;font-size:12px"><b>${state.completed.length} of 32 lessons</b><b>${percentDone()}%</b></div>${meter(percentDone())}<small>Offline-first · Saved on this device</small></div><div class="developer-mark"><span class="developer-mark-symbol">✦</span><span><small>DESIGNED &amp; DEVELOPED BY</small><strong>Avinash Ekka</strong></span></div></aside>`}
const titles={fullacts:'Complete Legal Texts',actreader:'Official Code Reader',visuals:'Interactive Infographics',home:'Overview',learn:'Learn the Codes',module:'Code Overview',lesson:'Learning Reader',academy:'Learning Academy',quiz:'Quiz & Mock Tests',quizplay:'Knowledge Assessment',advisor:'Legal Tutor',glossary:'Legal Dictionary',compare:'Old vs New Laws',updates:'Legal Updates',compliance:'Compliance Explorer',calculator:'HR Calculators',planner:'Action Planner',documents:'Document Reviewer',reports:'Reports & Insights',settings:'Settings'};
function render(){document.documentElement.classList.toggle('light',state.theme==='light');document.documentElement.style.fontSize=(state.fontScale*100)+'%';app.innerHTML=`<div class="layout">${renderSide()}<div class="main"><header class="topbar lcp-v8-header" role="banner"><div class="v8-app-identity"><span class="v8-app-emblem" aria-hidden="true">⚖</span><span class="v8-app-name"><b>LabourCode Pro</b><small>READ · EXPLORE · UNDERSTAND</small></span></div><div class="breadcrumb"><span>LabourCode Pro</span><span> / </span><b>${esc(titles[view.route]||'Workspace')}</b></div><div class="top-right v8-toolbar"><span class="chip">● OFFLINE LEGAL LIBRARY</span><button type="button" class="header-tool v8-search-tool" data-go="search" aria-label="Search the legal library" title="Search the legal library">${icon('search',21)}<span>Search</span></button><button type="button" class="header-tool v8-theme-tool" data-action="theme" aria-pressed="${state.theme==='dark'}" aria-label="${state.theme==='dark'?'Switch to day mode':'Switch to night mode'}" title="${state.theme==='dark'?'Switch to day mode':'Switch to night mode'}">${icon(state.theme==='dark'?'sun':'moon',21)}<span>${state.theme==='dark'?'Day':'Night'}</span></button><button type="button" class="icon-btn v8-exit" data-action="exit" title="Exit app" aria-label="Exit app">${icon('exit')}</button><div class="top-developer" title="App developer">Developed by <b>Avinash Ekka</b></div></div></header><main class="workspace reveal">${renderView()}<footer class="workspace-footer"><span>LABOURCODE PRO <b>1.0</b> <i>•</i> EDUCATIONAL LEGAL REFERENCE</span><span>Developed by <strong>Avinash Ekka</strong></span></footer></main></div></div>`}
function section(title,more='',action=''){return `<div class="section-head"><h2>${title}</h2>${more?`<button class="btn ghost small" ${action}>${more} ${icon('arrow')}</button>`:''}</div>`}
function stat(label,val,em){return `<div class="stat"><span class="stat-icon">${em}</span><strong>${val}</strong><small>${esc(label)}</small></div>`}
function moduleCard(c){const v=Math.round(completedFor(c.id)/c.lessons.length*100);return `<article class="card module"><img class="module-art" src="assets/editorial_${c.id}.webp" alt="${att(c.name)} illustration" loading="lazy"><div class="module-inner"><span class="number">CODE ${esc(c.number)} · ${esc(c.category)}</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p>${meter(v)}<div class="module-foot"><small class="muted">${completedFor(c.id)} / ${c.lessons.length} lessons</small><button class="btn small secondary" data-go="module" data-code="${c.id}">Explore ${icon('arrow')}</button></div></div></article>`}
const roleShortcuts={
 hr:[['Compliance workspace','Review applicable obligations and operational checkpoints','compliance','compliance'],['Salary and HR calculations','Simulate illustrative wage, EPF, ESI and gratuity examples','calculator','calculator'],['Document review studio','Screen policies and letters for terms to investigate','documents','documents']],
 employee:[['Your learning rights','Understand protections and common employment terms','learn','learn'],['Legal dictionary','Learn concepts with practical explanations','glossary','glossary'],['Salary examples','Understand how different salary components interact','calculator','calculator']],
 employer:[['Applicability explorer','Work through a structured establishment review','compliance','compliance'],['Personal action planner','Record and export your own review milestones','planner','planner'],['Workforce cost scenarios','Explore illustrative financial and HR examples','calculator','calculator']],
 student:[['Learning Academy','Master concepts with structured lessons and badges','academy','academy'],['Mock examinations','Take timed exams and practice with feedback','quiz','quiz'],['Spaced repetition','Remember important legal terms with flashcards','flashcards','learn']],
 legal:[['Old versus new enactments','Map 29 former laws to the four Codes','compare','compare'],['Legal update centre','Review dated source links and official references','updates','updates'],['Document reviewer','Keyword-led educational review of workplace documents','documents','documents']]
};
const hindiHints={'Wages':'मजदूरी / वेतन','Worker':'श्रमिक','Employee':'कर्मचारी','Employer':'नियोक्ता','Gratuity':'उपदान / ग्रेच्युटी','Minimum wage':'न्यूनतम मजदूरी','Overtime':'अतिरिक्त समय का काम','Trade union':'श्रमिक संघ','Retrenchment':'छँटनी','Social security':'सामाजिक सुरक्षा','Maternity benefit':'मातृत्व लाभ','Fixed-term employment':'निश्चित अवधि का रोजगार'};
function quickCard(name,sub,route,ico){return `<button class="card" style="text-align:left;cursor:pointer;color:inherit" data-go="${route}"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px"><span style="color:var(--teal)">${icon(ico,25)}</span><span class="muted">${icon('arrow')}</span></div><h3>${name}</h3><p style="margin:0">${sub}</p></button>`}
function renderHome(){const p=percentDone();return `<div class="eyebrow">YOUR INTELLIGENT LEGAL LEARNING WORKSPACE</div><div style="display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:20px"><div><h1 class="heading">Good to see you, ${roleTitle().split(' ')[0]}.</h1><p class="subhead">Learn the law. Test your understanding. Apply it confidently.</p></div><span class="pill">Content snapshot: ${dateLabel(D.verified)}</span></div><div class="hero"><div><span class="hero-label">THE FOUR INDIAN LABOUR CODES</span><h1>Master labour law.<br>Build workplace confidence.</h1><p>32 guided lessons · 312 knowledge checks · practical HR labs · source-linked legal guidance. Your learning and saved progress work offline.</p><div class="actions"><button class="btn" data-go="learn">Continue learning ${icon('arrow')}</button><button class="btn secondary" data-go="quiz">Start an assessment</button></div></div><div class="hero-right"><div class="hero-ring"><div class="hero-ring-inner"><b>${p}%</b><small>Complete</small></div></div></div></div><div class="stats">${stat('Lessons completed',`${state.completed.length}/32`,'📖')}${stat('Available practice questions','312','🧠')}${stat('Best quiz score',state.scores.length?Math.round(Math.max(...state.scores.map(s=>100*s.correct/s.total)))+'%':'—','🏆')}${stat('Compliance review points','26','🛡️')}</div>${section('Explore the four Codes','Browse lessons','data-go="learn"')}<div class="grid-4">${D.codes.map(moduleCard).join('')}</div>${section(roleTitle()+' essentials','View all tools','data-go="compliance"')}<div class="grid-3">${(roleShortcuts[state.role]||roleShortcuts.hr).map(([name,desc,route,ico])=>quickCard(name,desc,route,ico)).join('')}</div><div style="margin-top:20px">${notice('This third-party educational app is not a government service. State-wise rules and notifications are not a live database; verify all legal answers against the operative legislation and official sources.')}</div>`}
function renderLearn(){return `<div class="eyebrow">COMPREHENSIVE LEARNING LIBRARY</div><h1 class="heading">Understand every Code, clearly.</h1><p class="subhead">Structured learning, legal definitions, practical examples and source-linked insights.</p><div class="stats">${stat('Central Labour Codes','4','⚖️')}${stat('Detailed lessons','32','📚')}${stat('Term explanations','60','🔎')}${stat('Practical case studies','12','💼')}</div><div class="grid-4">${D.codes.map(moduleCard).join('')}</div><div style="margin-top:21px" class="banner"><b>Understanding legal terms</b><p>Inside each lesson, tap underlined legal terms to open explanations with real-life examples and available Hindi translations.</p></div>`}
function renderModule(){const c=C[view.code];if(!c)return renderLearn();return `<div class="actions" style="margin-bottom:18px"><button class="btn ghost small" data-go="learn">${icon('back')} All Codes</button>${codePill(c.id)}</div><div class="hero" style="min-height:210px;padding:25px 30px"><div><div class="hero-label">CODE ${esc(c.number)} · ${esc(c.category)}</div><h1 style="font-size:30px">${esc(c.name)}</h1><p>${esc(c.description)}</p><div class="actions"><button class="btn" data-go="lesson" data-code="${c.id}" data-lesson="${c.lessons[0].id}">Start learning ${icon('arrow')}</button><button class="btn secondary" data-action="start-quiz" data-code="${c.id}" data-mode="topic">Test this Code</button><button class="btn hero-alt" data-go="actreader" data-code="${c.id}">Read full statutory text ${icon('arrow')}</button></div></div><div class="hero-right"><img src="assets/editorial_${c.id}.webp" alt="" style="width:100%;max-height:195px;object-fit:cover;border-radius:18px;box-shadow:0 12px 38px #0005"></div></div>${section(`Learning path · ${c.lessons.length} lessons`)}<div class="split"><div>${c.lessons.map((l,i)=>`<div class="list-row"><div class="num">${state.completed.includes(l.id)?icon('check'):String(i+1).padStart(2,'0')}</div><div class="body"><b>${esc(l.title)}</b><small>${esc(l.subtitle)} · ${l.readMin} min · ${esc(l.reference)}</small></div><button class="btn small ${state.completed.includes(l.id)?'ghost':'secondary'}" data-go="lesson" data-code="${c.id}" data-lesson="${l.id}">${state.completed.includes(l.id)?'Review':'Study'} ${icon('arrow')}</button></div>`).join('')}</div><div><div class="card"><h3>Module progress</h3><div class="big-number">${completedFor(c.id)}<span class="muted" style="font-size:18px"> / ${c.lessons.length}</span></div>${meter(completedFor(c.id)/c.lessons.length*100)}<p style="margin:15px 0 0">Every lesson includes a summary, real-world scenario, takeaways and relevant official-source references.</p></div><div class="card" style="margin-top:15px"><h3>Practical situations</h3>${c.cases.map((v,i)=>`<button class="list-row" style="width:100%;margin-top:11px;text-align:left" data-action="case" data-code="${c.id}" data-index="${i}"><div class="body"><b>${esc(v.title)}</b><small>${esc(short(v.situation,110))}</small></div>${icon('arrow')}</button>`).join('')}</div></div></div>`}
const termMap=new Map(D.glossary.map(t=>[t.term.toLowerCase(),t]));
const termWords=D.glossary.map(t=>t.term).filter(t=>t.length>3).sort((a,b)=>b.length-a.length);
const termRegex=new RegExp('\\b('+termWords.map(w=>w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')\\b','gi');
function linked(s){return String(s||'').split(termRegex).map(part=>{const t=termMap.get(part.toLowerCase());return t?`<button class="term" data-action="term" data-term="${att(t.term)}" title="Explain: ${att(t.term)}">${esc(part)}</button>`:esc(part)}).join('')}
function renderLesson(){let c=C[view.code],l=c?.lessons.find(x=>x.id===view.lesson);if(!l)return renderModule();let idx=c.lessons.indexOf(l);return `<div class="actions" style="margin-bottom:16px"><button class="btn ghost small" data-go="module" data-code="${c.id}">${icon('back')} ${esc(ALL[c.id])}</button><span class="pill">LESSON ${idx+1} OF 8</span><span class="pill">${l.readMin} MIN READ</span></div><div class="split"><article class="card lesson-body"><div class="eyebrow">${esc(c.name)} · ${esc(l.reference)}</div><h1 class="heading">${esc(l.title)}</h1><p class="subhead">${esc(l.subtitle)}</p><div class="hr-line"></div><p class="summary">${linked(l.summary)}</p>${l.paragraphs.map(x=>`<p>${linked(x)}</p>`).join('')}<div class="notes"><b>Key takeaways</b><ul>${l.takeaways.map(x=>`<li>${linked(x)}</li>`).join('')}</ul></div><div class="case"><span class="kicker">WORKPLACE EXAMPLE</span><p>${linked(l.example)}</p></div><div class="hr-line"></div><p class="tiny">Source reference: ${esc(l.reference)} · Reviewed ${dateLabel(l.lastReviewed)}</p><p><button class="btn secondary small" data-go="actreader" data-code="${c.id}">Read complete original Code ${icon('arrow')}</button></p><div class="actions" style="margin-top:22px"><button class="btn" data-action="complete" data-id="${l.id}">${state.completed.includes(l.id)?'✓ Marked complete':'✓ Mark lesson complete'}</button><button class="btn secondary" data-action="bookmark" data-id="${l.id}">${icon('bookmark')} ${state.bookmarks.includes(l.id)?'Remove bookmark':'Bookmark'}</button><button class="btn ghost" data-action="speak" data-id="${l.id}">${icon('speaker')} Read aloud</button></div><div class="actions" style="justify-content:space-between;margin-top:20px"><div>${idx>0?`<button class="btn ghost" data-go="lesson" data-code="${c.id}" data-lesson="${c.lessons[idx-1].id}">${icon('back')} Previous</button>`:''}</div><div>${idx<c.lessons.length-1?`<button class="btn secondary" data-go="lesson" data-code="${c.id}" data-lesson="${c.lessons[idx+1].id}">Next lesson ${icon('arrow')}</button>`:`<button class="btn secondary" data-action="start-quiz" data-code="${c.id}" data-mode="topic">Take module quiz ${icon('arrow')}</button>`}</div></div></article><aside><div class="card"><h3>Learning completion</h3><div class="big-number">${Math.round(completedFor(c.id)/8*100)}%</div>${meter(completedFor(c.id)/8*100)}<p>Progress is saved locally on this Windows PC.</p></div><div class="card" style="margin-top:16px"><h3>Context matters</h3><p>These are educational summaries, not operative legal determinations. Check definitions, jurisdiction, sector and the latest rules.</p>${codePill(c.id)}</div><div class="card" style="margin-top:16px"><h3>Quick concept lookup</h3><p>Tap highlighted concepts in the lesson text to explore legal definitions.</p><button class="btn secondary small" data-go="glossary">Browse dictionary ${icon('arrow')}</button></div></aside></div>`}
function renderQuizLanding(){return `<div class="eyebrow">ASSESS · RECALL · MASTER</div><h1 class="heading">Knowledge Assessments</h1><p class="subhead">Practise legal concepts, simulate decisions, then review detailed explanations.</p><div class="stats">${stat('Question bank',D.questions.length,'❓')}${stat('Completed tests',state.scores.length,'✅')}${stat('Highest test score',state.scores.length?Math.round(Math.max(...state.scores.map(s=>s.correct/s.total*100)))+'%':'—','🏅')}${stat('Scenario questions',D.questions.filter(q=>q.scenario).length,'💭')}</div>${section('Choose an assessment')}<div class="grid-3">${[
 ['quick','Quick knowledge check','10 questions from across all four Codes. A fast check-up for busy days.','10 questions','⚡'],
 ['adaptive','Adaptive practice','A mix of foundational and scenario-style questions, informed by prior scores.','15 questions','🧠'],
 ['mock','Timed mock examination','30 mixed questions, 15-minute timer and detailed final review.','30 questions','⏱'],
 ['scenario','Scenario challenges','Test your legal reasoning against workplace-style situations.','10 questions','💼'],
 ['daily','Daily five','A repeatable five-question set that changes every day.','5 questions','📅']
 ].map(([k,t,p,n,em])=>`<div class="card"><div style="font-size:26px;margin-bottom:14px">${em}</div><h3>${t}</h3><p>${p}</p><div class="actions"><span class="pill">${n}</span><button class="btn small" data-action="start-quiz" data-mode="${k}" data-code="all">Begin ${icon('arrow')}</button></div></div>`).join('')}</div>${section('Tests by Code')}<div class="grid-4">${D.codes.map(c=>`<div class="card"><div class="kicker" style="color:${c.color}">${c.short}</div><h3 style="margin:12px 0">${esc(ALL[c.id])}</h3><p>${D.questions.filter(q=>q.code===c.id).length} questions in the bank</p><button class="btn secondary small" data-action="start-quiz" data-mode="topic" data-code="${c.id}">Start Code quiz</button></div>`).join('')}</div>${section('Recent attempts')}<div class="card">${state.scores.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Assessment</th><th>Coverage</th><th>Score</th></tr></thead><tbody>${state.scores.slice(-8).reverse().map(s=>`<tr><td>${esc(s.date)}</td><td>${esc(s.mode)}</td><td>${esc(s.code==='all'?'All Codes':ALL[s.code])}</td><td><b>${s.correct}/${s.total} · ${Math.round(s.correct/s.total*100)}%</b></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Your assessment history will appear after your first completed quiz.</div>`}</div>${notice('These quizzes are self-study practice, not accredited examinations. The expanded bank includes algorithmically generated variants that have not been individually vetted by a lawyer.')}`}
function seededSort(items,seed){let a=items.slice();for(let i=a.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;let j=seed%(i+1);[a[i],a[j]]=[a[j],a[i]]};return a}
function startQuiz(mode='quick',code='all'){
  const qPool=D.questions.filter(q=>(code==='all'||q.code===code)&& (mode!=='scenario'||q.scenario));
  const count=mode==='daily'?5:mode==='quick'?10:mode==='adaptive'?15:mode==='mock'?30:mode==='topic'?12:10;
  const day=new Date().toISOString().slice(0,10);
  const seed=mode==='daily'?Number(day.replace(/-/g,'')):Math.floor(Math.random()*999999);
  let questions=seededSort(qPool.length?qPool:D.questions,seed).slice(0,count);
  if(mode==='adaptive'&&state.scores.length){let weak=D.codes.slice().sort((a,b)=>mastery(a.id)-mastery(b.id))[0];let extra=seededSort(D.questions.filter(q=>q.code===weak.id&&!questions.includes(q)),seed+23).slice(0,4);questions=seededSort([...extra,...questions.slice(0,count-extra.length)],seed+31)}
  view.quiz={mode,code,questions,idx:0,selected:null,checked:false,answers:[],endAt:mode==='mock'?Date.now()+15*60*1000:null,finished:false};go('quizplay');
}
function renderQuizPlay(){const v=view.quiz;if(!v)return renderQuizLanding();if(v.finished)return renderQuizFinish();const q=v.questions[v.idx];if(!q)return renderQuizLanding();let remaining=v.endAt?Math.max(0,Math.round((v.endAt-Date.now())/1000)):0;return `<div class="actions" style="justify-content:space-between;margin-bottom:18px"><button class="btn ghost small" data-go="quiz">${icon('back')} All assessments</button><span class="pill">${v.mode.toUpperCase()} ${v.endAt?`· <b id="countdown">${clock(remaining)}</b> remaining`:''}</span></div><div class="split"><div class="card"><div class="kicker">QUESTION ${v.idx+1} OF ${v.questions.length}</div><div class="progress-pips">${v.questions.map((_,i)=>`<i class="${i===v.idx?'current':i<v.idx?'done':''}"></i>`).join('')}</div><div class="tagrow">${codePill(q.code)}${q.scenario?'<span class="pill">Scenario-based</span>':''}</div><div class="quiz-question">${esc(q.question)}</div>${q.options.map((op,i)=>`<button class="option ${v.selected===i?'selected':''} ${v.checked&&i===q.answer?'correct':''} ${v.checked&&v.selected===i&&i!==q.answer?'incorrect':''}" data-action="answer" data-index="${i}" ${v.checked?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(op)}</span>${v.checked&&i===q.answer?icon('check'):''}</button>`).join('')}${v.checked?`<div class="answer-note"><b style="color:${v.selected===q.answer?'var(--green)':'var(--red)'}">${v.selected===q.answer?'Correct answer':'Review the correct answer'}</b><p style="margin:7px 0">${esc(q.explanation)}</p><small class="muted">Reference: ${esc(q.reference)}</small></div>`:''}<div class="actions" style="justify-content:space-between;margin-top:22px"><span class="muted tiny">Questions require one answer each.</span><button class="btn" data-action="quiz-next" ${!v.checked||v.selected===null?'disabled':''}>${v.idx===v.questions.length-1?'Finish assessment':'Next question'} ${icon('arrow')}</button></div></div><div><div class="card"><h3>Assessment progress</h3><div class="big-number">${v.idx+1}<span style="font-size:19px" class="muted"> / ${v.questions.length}</span></div>${meter(v.idx/v.questions.length*100)}<p>Explanations are shown after you select each answer.</p></div><div class="card" style="margin-top:16px"><h3>Study guidance</h3><p>Use the original statutory texts and relevant Rules to verify actual legal obligations. Quiz performance measures understanding of this educational content.</p></div></div></div>`}
function clock(sec){let m=Math.floor(sec/60),s=sec%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function finalizeQuiz(){let q=view.quiz;if(!q||q.finished)return;q.finished=true;const correct=q.answers.filter(x=>x.correct).length;q.correct=correct;state.scores.push({date:new Date().toISOString().slice(0,10),mode:q.mode,code:q.code,correct,total:q.questions.length});state.scores=state.scores.slice(-150);addStudy();markSaved();render()}
function renderQuizFinish(){const q=view.quiz;const pct=Math.round(q.correct/q.questions.length*100);return `<div class="eyebrow">ASSESSMENT COMPLETE</div><div class="split"><div class="card" style="text-align:center;padding:38px"><div style="font-size:44px;margin-bottom:10px">${pct>=80?'🏆':pct>=60?'⭐':'📚'}</div><h1 class="heading">${pct>=80?'Excellent progress!':pct>=60?'Keep building mastery':'Every practice session counts'}</h1><div class="big-number" style="color:var(--teal);font-size:60px;margin:14px">${pct}%</div><p>${q.correct} correct out of ${q.questions.length} questions</p>${meter(pct)}<div class="actions" style="justify-content:center;margin-top:22px"><button class="btn" data-action="start-quiz" data-code="${q.code}" data-mode="${q.mode}">Try another ${icon('arrow')}</button><button class="btn secondary" data-go="academy">View analytics</button><button class="btn ghost" data-go="quiz">All tests</button></div></div><div class="card"><h3>Attempt review</h3>${q.answers.map((a,i)=>`<div class="list-row"><div class="num" style="color:${a.correct?'var(--green)':'var(--red)'}">${a.correct?'✓':'✕'}</div><div class="body"><b>${esc(short(q.questions[i].question,110))}</b><small>${esc(q.questions[i].explanation)}</small></div></div>`).join('')}</div></div>`}
function radar(){const scores=D.codes.map(c=>mastery(c.id));const center=140,rad=102;const p=(i,r)=>{const a=-Math.PI/2+i*Math.PI/2;return [(center+Math.cos(a)*r).toFixed(1),(center+Math.sin(a)*r).toFixed(1)].join(',')};const pts=scores.map((s,i)=>p(i,Math.max(s,3)/100*rad)).join(' ');return `<svg viewBox="0 0 280 280" role="img" aria-label="Four Code mastery radar chart">${[.25,.5,.75,1].map(k=>`<polygon points="${[0,1,2,3].map(i=>p(i,k*rad)).join(' ')}" fill="none" stroke="currentColor" stroke-opacity=".16"/>`).join('')}${[0,1,2,3].map(i=>`<path d="M140 140L${p(i,rad).replace(',',' ')}" stroke="currentColor" stroke-opacity=".14"/>`).join('')}<polygon points="${pts}" fill="#59dcc04a" stroke="#62e2c2" stroke-width="2.5"/><text x="140" y="23" text-anchor="middle" font-size="10" fill="currentColor">WAGES</text><text x="250" y="144" text-anchor="middle" font-size="9" fill="currentColor">IR</text><text x="140" y="263" text-anchor="middle" font-size="10" fill="currentColor">SOCIAL</text><text x="30" y="144" text-anchor="middle" font-size="9" fill="currentColor">OSH</text></svg>`}
function awardBadges(){const best=state.scores.length?Math.round(Math.max(...state.scores.map(s=>s.correct/s.total*100))):0;return [
 ['First Steps','Complete your first lesson',state.completed.length>=1,'📖'],
 ['Consistent Learner','Complete 12 lessons',state.completed.length>=12,'🌟'],
 ['Code Explorer','Complete all 32 lessons',state.completed.length===32,'🎓'],
 ['Knowledge Champion','Score 80% in a quiz',best>=80,'🏆'],
 ['Practice Pro','Complete 5 assessments',state.scores.length>=5,'🧠'],
 ['Compliance Explorer','Review at least 10 checklist items',state.checkmarks.length>=10,'🛡️']];}
function renderAcademy(){const best=state.scores.length?Math.round(Math.max(...state.scores.map(s=>s.correct/s.total*100))):0;const cert=state.completed.length>=16&&best>=70;return `<div class="eyebrow">PERSONALISED LEARNING ACADEMY</div><h1 class="heading">Your path to mastery</h1><p class="subhead">Track knowledge, strengthen weak areas and revisit concepts with spaced repetition.</p><div class="stats">${stat('Learning progress',`${percentDone()}%`,'📘')}${stat('Assessment attempts',state.scores.length,'🧠')}${stat('Achievements',awardBadges().filter(x=>x[2]).length+'/6','🏅')}${stat('Saved bookmarks',state.bookmarks.length,'🔖')}</div><div class="split"><div class="card"><div class="section-head" style="margin:0 0 15px"><h2>Mastery by Code</h2><span class="pill">Based on practice scores</span></div><div class="chartbox">${radar()}</div><div class="barchart">${D.codes.map(c=>`<div class="barrow"><span>${esc(ALL[c.id])}</span><div class="bar"><span style="width:${mastery(c.id)}%"></span></div><b>${mastery(c.id)}%</b></div>`).join('')}</div></div><div><div class="card"><h3>Self-study milestone</h3><div style="font-size:35px;margin:12px 0">${cert?'🎓':'🏁'}</div><p>Complete 16 lessons and achieve at least 70% in a quiz to unlock a non-accredited learning certificate.</p><p><b>${state.completed.length} / 16 lessons</b> · <b>${best}% / 70% best score</b></p><button class="btn" ${cert?'data-action="certificate"':'disabled'}>View certificate ${icon('arrow')}</button></div><div class="card" style="margin-top:17px"><h3>Personal improvement plan</h3><p>Your weakest measured Code: <b>${esc(ALL[D.codes.slice().sort((a,b)=>mastery(a.id)-mastery(b.id))[0].id])}</b>.</p><div class="actions"><button class="btn secondary small" data-go="flashcards">Revise flashcards</button><button class="btn secondary small" data-go="quiz">Practise questions</button></div></div></div></div>${section('Interactive learning tools')}<div class="grid-3">${quickCard('Spaced-repetition flashcards','Flip legal-term cards and schedule the next review','flashcards','learn')}${quickCard('Daily knowledge challenge','Five questions picked for today','quiz','quiz')}${quickCard('Legal concept matching','Match legal concepts with their meaning','matching','glossary')}</div>${section('Your learning badges')}<div class="grid-3">${awardBadges().map(([name,desc,earned,emoji])=>`<div class="card" style="opacity:${earned?'1':'.55'}"><div style="font-size:33px;margin-bottom:10px">${emoji}</div><h3>${name} ${earned?'✓':''}</h3><p style="margin:0">${desc}</p></div>`).join('')}</div>${section('Saved reading bookmarks')}<div class="card">${state.bookmarks.length?state.bookmarks.map(id=>{let l=allLessons.find(x=>x.id===id);return l?`<div class="list-row"><div class="body"><b>${esc(l.title)}</b><small>${esc(l.codeName)}</small></div><button class="btn secondary small" data-go="lesson" data-code="${l.code}" data-lesson="${l.id}">Open</button></div>`:''}).join(''):'<div class="empty">Bookmark any lesson to find it here.</div>'}</div>`}
function dueTerms(){const now=Date.now();return D.glossary.filter(x=>!state.flashcards[x.term]||new Date(state.flashcards[x.term].next).getTime()<=now)}
function renderFlashcards(){const list=view.flashFilter==='due'?dueTerms():D.glossary;let idx=(view.flashIdx%Math.max(1,list.length));const t=list[idx];return `<div class="actions" style="margin-bottom:15px"><button class="btn ghost small" data-go="academy">${icon('back')} Academy</button><span class="pill">${dueTerms().length} terms due for review</span></div><div class="eyebrow">ACTIVE RECALL · SPACED REPETITION</div><h1 class="heading">Flashcard Studio</h1><p class="subhead">Try to define the term before revealing its explanation.</p><div class="lesson-tabs" style="margin:20px 0"><button class="tab ${view.flashFilter==='all'?'active':''}" data-action="flash-filter" data-filter="all">All 60 terms</button><button class="tab ${view.flashFilter==='due'?'active':''}" data-action="flash-filter" data-filter="due">Due for review (${dueTerms().length})</button></div>${t?`<div class="flash-card" style="max-width:760px;margin:auto"><div class="caption">CARD ${idx+1} OF ${list.length}</div><h2>${esc(t.term)}</h2>${view.flashRevealed?`<p>${esc(t.definition)}</p><p class="tiny">Example: ${esc(t.example)}</p>`:`<p>Think of the definition. Click Reveal answer when ready.</p>`}</div><div class="actions" style="justify-content:center;margin-top:19px"><button class="btn secondary" data-action="flash-prev">${icon('back')} Previous</button>${view.flashRevealed?`<button class="btn" data-action="flash-rate" data-rate="again">Study again (1 day)</button><button class="btn" data-action="flash-rate" data-rate="good">Remembered (3 days)</button><button class="btn" data-action="flash-rate" data-rate="easy">Easy (7 days)</button>`:`<button class="btn" data-action="flash-reveal">Reveal explanation</button>`}<button class="btn secondary" data-action="flash-next">Next ${icon('arrow')}</button></div>`:'<div class="empty"><strong>All caught up!</strong><p>No cards due right now. Switch to All 60 terms to practise more.</p></div>'}`}
let matching={active:false,items:[],selectedTerm:null,matched:[],mistakes:0};
function startMatching(){let items=seededSort(D.glossary,Date.now()%999999).slice(0,5);matching={active:true,items,selectedTerm:null,matched:[],mistakes:0};go('matching')}
function renderMatching(){if(!matching.active)startMatchingNoRender();const done=matching.matched.length===matching.items.length;return `<div class="actions" style="margin-bottom:17px"><button class="btn ghost small" data-go="academy">${icon('back')} Academy</button></div><div class="eyebrow">INTERACTIVE TERM MATCHING</div><h1 class="heading">Match meaning to concept</h1><p class="subhead">Select a legal term, then choose its corresponding definition.</p><div class="card" style="max-width:980px;margin-top:22px"><div class="actions"><span class="pill">${matching.matched.length} / 5 matched</span><span class="pill">${matching.mistakes} retries</span><button class="btn ghost small" data-action="restart-matching">New cards</button></div>${done?`<div class="empty"><h2>Well done! 🎉</h2><p>You've matched every term. Try another round to reinforce the concepts.</p><button class="btn" data-action="restart-matching">Play again</button></div>`:`<div class="grid-2" style="margin-top:22px"><div><h3>Legal terms</h3>${matching.items.map((x,i)=>`<button class="option ${matching.selectedTerm===x.term?'selected':''} ${matching.matched.includes(x.term)?'correct':''}" data-action="match-term" data-term="${att(x.term)}" ${matching.matched.includes(x.term)?'disabled':''}>${esc(x.term)}</button>`).join('')}</div><div><h3>Definitions</h3>${seededSort(matching.items,222).map((x,i)=>`<button class="option ${matching.matched.includes(x.term)?'correct':''}" data-action="match-definition" data-term="${att(x.term)}" ${matching.matched.includes(x.term)?'disabled':''}>${esc(short(x.definition,170))}</button>`).join('')}</div></div>`}</div>`}
function startMatchingNoRender(){matching={active:true,items:seededSort(D.glossary,Date.now()%999999).slice(0,5),selectedTerm:null,matched:[],mistakes:0}}
function searchResults(query){const terms=String(query).toLowerCase().trim().split(/\s+/).filter(w=>w.length>2).slice(0,12);if(!terms.length)return[];const results=[];
  for(const l of allLessons){let text=[l.title,l.summary,...l.paragraphs,l.example].join(' ').toLowerCase();let score=terms.reduce((sum,t)=>sum+(l.title.toLowerCase().includes(t)?6:0)+(l.summary.toLowerCase().includes(t)?3:0)+(text.includes(t)?1:0),0);if(score)results.push({type:'lesson',name:l.title,description:l.summary,code:l.code,lesson:l.id,score,source:l.sourceUrl})}
  for(const t of D.glossary){let text=(t.term+' '+t.definition+' '+t.example).toLowerCase();let score=terms.reduce((sum,k)=>sum+(t.term.toLowerCase().includes(k)?6:0)+(text.includes(k)?2:0),0);if(score)results.push({type:'term',name:t.term,description:t.definition,term:t.term,score})}
  for(const v of allCases){let txt=[v.title,v.situation,v.analysis].join(' ').toLowerCase();let score=terms.reduce((a,k)=>a+(v.title.toLowerCase().includes(k)?4:0)+(txt.includes(k)?1:0),0);if(score)results.push({type:'case',name:v.title,description:v.situation,code:v.code,index:C[v.code].cases.findIndex(c=>c.title===v.title),score})}
  return results.sort((a,b)=>b.score-a.score).slice(0,18)
}
function renderSearch(){const results=searchResults(view.query);return `<div class="eyebrow">SEARCH ACROSS YOUR LAW LIBRARY</div><h1 class="heading">Find answers faster.</h1><p class="subhead">Search 32 lessons, 60 legal definitions and practical workplace cases—completely offline.</p><div class="searchbox" style="margin:25px 0;max-width:810px">${icon('search')}<input id="global-search" class="input" placeholder="Search wages, retrenchment, PF, overtime, contracts..." value="${att(view.query)}" autocomplete="off"></div><div class="actions"><span class="pill">${view.query?results.length+' results':'Type a term or question to begin'}</span><button class="btn ghost small" data-go="glossary">Legal dictionary</button></div><div style="margin-top:20px">${view.query?results.map(r=>`<div class="list-row"><div class="num">${r.type==='term'?'Aa':r.type==='case'?'💼':'📖'}</div><div class="body"><b>${esc(r.name)}</b><small>${esc(short(r.description,190))}</small></div><span class="pill">${esc(r.type)}</span><button class="btn secondary small" ${r.type==='lesson'?`data-go="lesson" data-code="${r.code}" data-lesson="${r.lesson}"`:r.type==='term'?`data-action="term" data-term="${att(r.term)}"`:`data-action="case" data-code="${r.code}" data-index="${r.index}"`}>Open</button></div>`).join('')||'<div class="empty">No matching content. Try a shorter term or related concept.</div>':`<div class="grid-3">${[['wages','Wages'],['security','Social Security'],['industrial','Trade Unions']].map(([k,title])=>`<button class="card" data-action="search-example" data-query="${title}" style="text-align:left;color:inherit"><h3>${title} ${icon('arrow')}</h3><p style="margin:0">Explore lessons and definitions.</p></button>`).join('')}</div>`}</div>`}
function renderGlossary(){const q=view.glossaryQuery.toLowerCase(),items=D.glossary.filter(t=>(t.term+' '+t.definition+' '+t.example).toLowerCase().includes(q)&&(view.filteredCode==='all'||t.code==='all'||t.code===view.filteredCode));return `<div class="eyebrow">TAP TO EXPLAIN LEGAL TERMS</div><h1 class="heading">Smart Legal Dictionary</h1><p class="subhead">60 accessible explanations with plain-English definitions and workplace examples.</p><div class="card" style="margin:22px 0"><div class="form-row"><div class="searchbox">${icon('search')}<input id="glossary-search" class="input" placeholder="Find a legal concept..." value="${att(view.glossaryQuery)}"></div><div><select id="glossary-code"><option value="all">All four Codes</option>${D.codes.map(c=>`<option value="${c.id}" ${view.filteredCode===c.id?'selected':''}>${esc(ALL[c.id])}</option>`).join('')}</select></div></div></div><div class="grid-2">${items.map(t=>`<button class="card" style="text-align:left;color:inherit;cursor:pointer" data-action="term" data-term="${att(t.term)}"><div class="actions" style="justify-content:space-between"><span class="kicker">LEGAL TERM</span><span class="muted">${icon('arrow')}</span></div><h3 style="margin:12px 0">${esc(t.term)}</h3><p style="margin:0">${esc(short(t.definition,172))}</p></button>`).join('')||'<div class="empty">No matching definitions. Try another keyword.</div>'}</div>`}
function answerOffline(question){const res=searchResults(question).filter(r=>r.type==='lesson'||r.type==='term').slice(0,4);return res}
function renderAdvisor(){const a=view.tutorAnswer;return `<div class="eyebrow">SOURCE-GROUNDED LEARNING ASSISTANT</div><h1 class="heading">Legal Tutor</h1><p class="subhead">Ask a question and explore linked learning excerpts. Offline mode is a content retrieval tool, not a generative AI model.</p><div class="split" style="margin-top:24px"><div><div class="card"><div class="lesson-tabs" style="margin-bottom:18px"><button class="tab ${view.tutorMode==='offline'?'active':''}" data-action="tutor-mode" data-mode="offline">● Offline knowledge search</button><button class="tab ${view.tutorMode==='cloud'?'active':''}" data-action="tutor-mode" data-mode="cloud">✦ Optional cloud AI</button></div>${view.tutorMode==='cloud'?`<div class="banner warn" style="margin-bottom:15px"><b>External service / privacy</b><p>Cloud mode requires your separately deployed authenticated HTTPS /ask backend, such as the optional Python backend in the Android project. Questions and relevant law excerpts are sent only when you choose Ask. Do not enter personal or confidential HR data.</p></div><div class="field" style="margin-bottom:12px"><label>Backend HTTPS URL (ending in /ask)</label><input class="input" id="cloud-endpoint" placeholder="https://your-server.example/ask" value="${att(state.cloudEndpoint||'')}"></div><div class="field" style="margin-bottom:15px"><label>Backend access token (kept in memory for this session)</label><input type="password" class="input" id="cloud-token" value="${att(cloudBearer)}" placeholder="Your server's bearer token"></div>`:''}<div class="field"><label>Your question</label><textarea id="tutor-question" placeholder="Example: What does the Code on Wages say about excluded salary components?">${esc(view.tutorAsk)}</textarea></div><div class="actions" style="justify-content:space-between;margin-top:16px"><span class="pill">${view.tutorMode==='offline'?'Private and offline':'Opt-in external server'}</span><button class="btn" data-action="ask">${icon('advisor')} Find an explanation</button></div></div><div style="margin-top:19px">${a?`<div class="card"><span class="kicker">${a.cloud?'OPTIONAL CLOUD ANSWER':'RELEVANT OFFLINE EXCERPTS'}</span><h3 style="margin:13px 0">${esc(a.question)}</h3>${a.error?`<div class="banner warn"><b>Could not complete request</b><p>${esc(a.error)}</p></div>`:a.cloud?`<p style="white-space:pre-wrap;color:var(--ink)">${linked(a.answer||'')}</p>`:a.results.length?`${a.results.map((r,i)=>`<div class="case" style="margin:12px 0"><div class="actions"><span class="pill">MATCH ${i+1} · ${esc(r.type)}</span>${r.code?codePill(r.code):''}</div><h3 style="margin:12px 0 7px">${esc(r.name)}</h3><p>${linked(r.description)}</p>${r.source?`<p>${extlink(r.source,'Original Code source')}</p>`:''}<button class="btn ghost small" ${r.type==='lesson'?`data-go="lesson" data-code="${r.code}" data-lesson="${r.lesson}"`:`data-action="term" data-term="${att(r.term)}"`}>Open full reference ${icon('arrow')}</button></div>`).join('')}`:'<p>No close matches were found in the offline dataset. Try specific terms such as gratuity, fixed-term or overtime.</p>'}<div class="banner warn" style="margin-top:16px"><b>Check before acting</b><p>Educational assistance is not a legal opinion. Verify operative Codes, State/Central Rules, notifications and facts before making decisions.</p></div></div>`:''}</div></div><aside><div class="card"><h3>Try these questions</h3>${['What does wages mean in the Codes?','How do standing orders work?','Are EPF and ESI the same?','What safety duties apply to employers?'].map(s=>`<button class="list-row" style="width:100%;text-align:left" data-action="tutor-example" data-query="${att(s)}"><div class="body"><b>${esc(s)}</b></div>${icon('arrow')}</button>`).join('')}</div><div class="card" style="margin-top:16px"><h3>Primary sources</h3>${D.codes.map(c=>`<p style="margin:7px 0">${extlink(c.source,ALL[c.id])}</p>`).join('')}<p>${extlink(P.official,'Ministry of Labour & Employment')}</p></div></aside></div>`}
function renderCompare(){return `<div class="eyebrow">BEFORE & AFTER · CONSOLIDATION MAP</div><h1 class="heading">29 former Acts. Four Labour Codes.</h1><p class="subhead">Explore how the previous central labour enactments are mapped into the consolidated Codes. This is a reference map, not a section-by-section legal equivalence.</p><div class="stats">${stat('Previous central Acts',29,'📜')}${stat('Consolidated Codes',4,'⚖️')}${stat('Central commencement','2025','📅')}${stat('Knowledge modules',32,'📘')}</div>${D.codes.map(c=>`<div class="card" style="margin-bottom:18px"><div class="actions" style="justify-content:space-between;margin-bottom:15px"><div><div class="kicker">CODE ${c.number} · ${P.oldActs[c.id].length} PREVIOUS ACTS</div><h3 style="margin:8px 0">${esc(c.name)}</h3></div>${codePill(c.id)}</div><div class="split"><div class="card" style="background:var(--panel2);box-shadow:none"><h4>Former central enactments</h4>${P.oldActs[c.id].map((s,i)=>`<div class="list-row" style="margin-top:8px;margin-bottom:0"><div class="num">${i+1}</div><div class="body"><b>${esc(s)}</b></div></div>`).join('')}</div><div class="card" style="background:var(--panel2);box-shadow:none"><h4>Study this Code</h4><p>${esc(c.description)}</p><p>All coverage claims depend on statutory text, repeal/savings provisions, relevant government and rules.</p><button class="btn" data-go="module" data-code="${c.id}">Explore ${esc(ALL[c.id])} ${icon('arrow')}</button><p>${extlink(c.source,'Official original text')}</p></div></div></div>`).join('')}${notice('A consolidated map does not mean every prior requirement has an exact equivalent. Read individual commencement, repeal, saving and applicability provisions and current Rules for professional use.')}`}
function renderUpdates(){return `<div class="eyebrow">EDITORIAL KNOWLEDGE SNAPSHOT</div><h1 class="heading">Legal Update Centre</h1><p class="subhead">Dated reference points and direct links to official sources. This is not automatic monitoring of new notifications.</p><div class="banner good" style="margin:23px 0"><b>Current packaged snapshot · 8 November 2026</b><p>Use the linked Ministry portal for the latest Central Rules, corrigenda, notifications and any new amendments. State rules must be checked separately.</p></div><div class="split"><div>${P.updates.slice().reverse().map(u=>`<div class="card" style="margin-bottom:15px"><div class="actions"><span class="pill">${esc(u.kind)}</span><span class="muted tiny">${dateLabel(u.date)}</span></div><h3 style="margin:13px 0">${esc(u.title)}</h3><p>${esc(u.description)}</p>${extlink(u.source,'Read official source')}</div>`).join('')}</div><div><div class="card"><h3>Official legal reference links</h3>${D.references.map(x=>`<div class="list-row"><div class="body"><b>${extlink(x.url,x.title)}</b></div></div>`).join('')}</div><div class="card" style="margin-top:15px"><h3>Jurisdiction reminder</h3><p>India's labour framework includes relevant Central and State Rules. Rules may change; the offline package does not download updates by itself.</p><button class="btn secondary small" data-go="compliance">Explore applicability</button></div></div></div>`}
function statusBadge(t){return `<span class="pill" style="color:${t?'var(--teal)':'var(--muted)'}">${t?'✓ Reviewed':'Not reviewed'}</span>`}
function renderCompliance(){const head=Math.max(0,num(state.companyHeadcount||0)),checked=state.checkmarks.length;const relevant=P.checklist.filter(x=>x.threshold!=='all'&&head>=num(x.threshold));return `<div class="eyebrow">APPLICABILITY & COMPLIANCE REVIEW</div><h1 class="heading">Compliance Explorer</h1><p class="subhead">A guided research workspace for identifying areas to verify—not a live legal-rule engine or compliance certification.</p><div class="stats">${stat('Jurisdictions selectable',P.states.length,'🇮🇳')}${stat('Review checkpoints',P.checklist.length,'☑️')}${stat('Completed reviews',checked,'🛡️')}${stat('Threshold indicators',relevant.length,'⚑')}</div><div class="card" style="margin:20px 0"><h3>Establishment profile</h3><p>Provide context to surface indicative review markers. Scope and worker-count rules vary by provision.</p><div class="form-row"><div class="field"><label>State / Union Territory</label><select id="profile-state">${P.states.map(s=>`<option ${s===state.preferredState?'selected':''} value="${att(s)}">${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Applicable government (indicative)</label><select id="profile-gov"><option value="unsure" ${state.companyGov==='unsure'?'selected':''}>Not yet determined</option><option value="central" ${state.companyGov==='central'?'selected':''}>Central government</option><option value="state" ${state.companyGov==='state'?'selected':''}>State government</option></select></div><div class="field"><label>Industry / sector</label><select id="profile-industry">${[['general','Office / General'],['factory','Factory / Manufacturing'],['construction','Construction'],['mines','Mines'],['contract','Contract labour'],['ngo','Non-profit / Section 8'],['digital','Platform / Gig services']].map(([v,t])=>`<option value="${v}" ${state.companyIndustry===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Indicative employee / worker headcount</label><input type="number" min="0" max="10000000" step="1" class="input" id="company-headcount" value="${head}" placeholder="Enter workforce count"></div></div><div class="actions" style="margin-top:15px"><button class="btn" data-action="apply-profile">Refresh review flags ${icon('arrow')}</button><span class="muted tiny">Different sections count different categories and periods; this number is not a coverage determination.</span></div></div><div class="banner warn"><b>For ${esc(state.preferredState||'your jurisdiction')}: no live State Rules verification</b><p>The packaged content does not determine whether or how a specific State notification applies. Confirm each provision with the State Labour Department, the appropriate government and updated Central/State Rules.</p></div>${section('Indicative headcount review markers')}<div class="grid-4">${[10,20,50,300].map(n=>`<div class="card"><div class="kicker">REFERENCE HEADCOUNT ${n}</div><div class="big-number" style="color:${head>=n?'var(--teal)':'var(--muted)'}">${n}+</div><p style="margin-bottom:0">${head>=n?'Investigate provisions using this reference threshold':'Headcount below this reference; exceptions and alternative definitions may still apply'}</p></div>`).join('')}</div>${section('Compliance review checklist',`${checked} / ${P.checklist.length} reviewed`,'data-action="export-compliance"')}<div class="grid-2">${D.codes.map(c=>`<div class="card"><div class="actions" style="justify-content:space-between"><h3>${esc(ALL[c.id])}</h3>${codePill(c.id)}</div>${P.checklist.filter(x=>x.code===c.id).map(t=>{const id=P.checklist.indexOf(t);const done=state.checkmarks.includes(id);const flagged=t.threshold!=='all'&&head>=num(t.threshold);return `<label class="list-row" style="cursor:pointer;align-items:flex-start"><input type="checkbox" class="check" data-action="check" data-index="${id}" ${done?'checked':''} style="margin-top:3px"><span class="body"><b>${esc(t.title)}</b><small>${esc(t.detail)}</small>${t.threshold!=='all'?`<span class="pill" style="margin-top:7px;color:${flagged?'var(--gold)':'var(--muted)'}">${flagged?'⚑ Check applicable '+t.threshold+' marker':'Reference: '+t.threshold+' workers'}</span>`:''}</span></label>`}).join('')}</div>`).join('')}</div><div style="margin-top:20px">${notice('Thresholds are educational flags only. They do not establish legal applicability, required registration, a filing obligation, or an exemption. Each Code and subordinate Rule can use a different worker definition, establishment type or lookback period.')}</div>`}
const CALCS=[['wage','Wage definition'],['gratuity','Gratuity'],['epf','EPF'],['esi','ESI'],['overtime','Overtime'],['bonus','Bonus'],['leave','Leave'],['separation','Separation']];
const calcData={
 wage:{title:'50% exclusion / add-back study example',descr:'Illustrates a simplified wage-definition approach. Component eligibility and legal classification must be verified.',fields:[['included','Included wage components (₹)',24000],['excluded','Assumed eligible excluded amounts (₹)',36000],['total','Assumed total remuneration (₹)',60000]],disclaimer:'Actual calculation under section 2(y) requires correct classification of all components, statutory treatment of exclusions, and current rules.'},
 gratuity:{title:'General gratuity illustration',descr:'Demonstration of the familiar 15/26 factor, subject to service and covered-wage provisions.',fields:[['wage','Illustrative last drawn monthly wage (₹)',30000],['years','Illustrative counted service years',6]],disclaimer:'Eligibility, counted service, limits, fixed-term arrangements, wage definition and rounding rules need separate legal review.'},
 epf:{title:'EPF contributions scenario',descr:'A simple percentage illustration, not a payroll certification.',fields:[['wage','Assumed PF calculation wage (₹)',15000],['workerRate','Employee contribution rate (%)',12],['employerRate','Employer contribution rate (%)',12]],disclaimer:'Wage ceilings, pension allocation, exemptions, membership and applicable schemes can change employer/employee actual amounts.'},
 esi:{title:'ESI contribution scenario',descr:'Calculate employee and employer shares at rates you enter.',fields:[['wage','Assumed eligible monthly wage (₹)',18000],['workerRate','Employee rate (%)',0.75],['employerRate','Employer rate (%)',3.25]],disclaimer:'Rates in this example are user-editable assumptions, not verified real-time rates. First check coverage, wage eligibility and current notifications.'},
 overtime:{title:'Overtime compensation scenario',descr:'Illustrates hours × base hourly rate × selected multiplier.',fields:[['rate','Assumed hourly wage (₹)',150],['hours','Overtime hours',12],['multiple','Assumed overtime multiplier',2]],disclaimer:'Not everyone is entitled to the same overtime payment; calculate regular rate, daily/weekly limits and eligibility under applicable Code/Rules.'},
 bonus:{title:'Bonus calculation scenario',descr:'Compare an illustrative low-rate and high-rate calculation.',fields:[['monthly','Assumed eligible monthly amount (₹)',15000],['months','Assumed counted months',12],['low','Lower example rate (%)',8.33],['high','Higher example rate (%)',20]],disclaimer:'Bonus coverage, eligibility, calculation ceilings, set-on/set-off and allocable surplus may materially change statutory bonus.'},
 leave:{title:'Earned leave accrual scenario',descr:'Simple days-worked / accrual-divisor calculation.',fields:[['days','Eligible counted days worked',260],['divisor','Assumed accrual: 1 day per X days',20]],disclaimer:'Actual leave accrual, qualifying days, categories, carry-forward and sector rules may differ. Do not use this as entitlement determination.'},
 separation:{title:'Separation cost planning illustration',descr:'Model one possible last-wage-related provision using a user-selected factor.',fields:[['wage','Assumed monthly wage (₹)',30000],['years','Assumed counted service years',8],['factor','Illustrative days per service year',15]],disclaimer:'This does not decide whether retrenchment, notice, permission, gratuity or other separation payments are legally due.'}
};
function renderCalculator(){const sel=view.calculator,d=calcData[sel],out=view.calcResults;return `<div class="eyebrow">PRACTICAL HR FINANCIAL SIMULATORS</div><h1 class="heading">Calculation Studio</h1><p class="subhead">Explore the mechanics of common workplace calculations using editable teaching assumptions.</p><div class="lesson-tabs" style="margin:23px 0">${CALCS.map(([k,t])=>`<button class="tab ${k===sel?'active':''}" data-action="calc-tab" data-tab="${k}">${t}</button>`).join('')}</div><div class="split"><div class="card"><h3>${d.title}</h3><p>${d.descr}</p><div class="form-row">${d.fields.map(([key,label,val])=>`<div class="field"><label for="calc-${key}">${label}</label><input class="input" type="number" id="calc-${key}" data-calc-key="${key}" step="any" value="${view.calcInputs?.[sel]?.[key]??val}"></div>`).join('')}</div><div class="actions" style="margin-top:20px"><button class="btn" data-action="calculate">Calculate example ${icon('arrow')}</button><button class="btn ghost" data-action="calc-reset">Reset assumptions</button></div>${out?`<div class="banner good" style="margin-top:22px"><div class="kicker">ILLUSTRATIVE RESULT</div><h2 style="font-size:30px;margin:10px 0">${esc(out.title)}</h2><div style="font-size:29px;font-weight:800;color:var(--teal)">${esc(out.value)}</div><p>${esc(out.detail)}</p></div><div class="barchart" style="margin:18px 0">${out.items.map(([t,v])=>`<div class="barrow"><span>${esc(t)}</span><div class="bar"><span style="width:${Math.min(100,(v/Math.max(...out.items.map(x=>x[1]),1))*100)}%"></span></div><b>${esc(fmt(v))}</b></div>`).join('')}</div>`:''}</div><aside><div class="card"><div style="font-size:29px">🧮</div><h3>How to use this tool</h3><p>Adjust the assumptions, calculate, inspect the arithmetic and compare the output with the relevant Code and official Rules.</p><div class="hr-line"></div><h4>Legal qualifications</h4><p>${d.disclaimer}</p></div><div class="card" style="margin-top:17px"><h3>Continue studying</h3><p>Review the lessons associated with the calculation and follow the official legislation links.</p><button class="btn secondary small" data-go="module" data-code="${sel==='overtime'||sel==='leave'?'osh':sel==='epf'||sel==='esi'||sel==='gratuity'?'security':sel==='separation'?'industrial':'wages'}">Open relevant Code</button></div></aside></div>`}
function calculate(){const d=calcData[view.calculator],o={};d.fields.forEach(([k,lab,def])=>o[k]=Math.max(0,num(document.getElementById('calc-'+k)?.value??def)));view.calcInputs??={};view.calcInputs[view.calculator]=o;let result;
  switch(view.calculator){
    case 'wage':{const half=o.total/2,add=Math.max(0,o.excluded-half),base=o.included+add;result={title:'Illustrative adjusted wage amount',value:cash(base),detail:`Eligible exclusions (${cash(o.excluded)}) exceed half the assumed remuneration (${cash(half)}) by ${cash(add)}. Illustrative included wages after add-back: ${cash(base)}.`,items:[['Included',o.included],['Exclusions',o.excluded],['Add-back',add],['Result',base]]};break}
    case 'gratuity':{let resultAmount=o.wage*15*o.years/26;result={title:'Illustrative gratuity',value:cash(resultAmount),detail:`${cash(o.wage)} × 15 ÷ 26 × ${fmt(o.years)} assumed counted years. No statutory eligibility conclusion.`,items:[['Monthly wage',o.wage],['Illustration',resultAmount]]};break}
    case 'epf':{let a=o.wage*o.workerRate/100,b=o.wage*o.employerRate/100;result={title:'Illustrative combined contributions',value:cash(a+b),detail:`Employee ${cash(a)} + employer ${cash(b)} per assumed period. Employer pension/EPS allocation is not separately modelled.`,items:[['Employee',a],['Employer',b],['Combined',a+b]]};break}
    case 'esi':{let a=o.wage*o.workerRate/100,b=o.wage*o.employerRate/100;result={title:'Illustrative combined contributions',value:cash(a+b),detail:`Employee share ${cash(a)}; employer share ${cash(b)} using the entered assumptions.`,items:[['Employee',a],['Employer',b],['Combined',a+b]]};break}
    case 'overtime':{let v=o.rate*o.hours*o.multiple;result={title:'Illustrative overtime amount',value:cash(v),detail:`${fmt(o.hours)} overtime hours × ${cash(o.rate)} assumed hourly base × ${fmt(o.multiple)} multiplier.`,items:[['Ordinary hours value',o.rate*o.hours],['Overtime pay',v]]};break}
    case 'bonus':{let a=o.monthly*o.months*o.low/100,b=o.monthly*o.months*o.high/100;result={title:'Illustrative bonus band',value:`${cash(a)} – ${cash(b)}`,detail:`${fmt(o.months)} assumed eligible months; rates ${fmt(o.low)}% to ${fmt(o.high)}%.`,items:[['Lower example',a],['Higher example',b]]};break}
    case 'leave':{let v=o.divisor>0?o.days/o.divisor:0;result={title:'Illustrative accrued days',value:fmt(v)+' days',detail:`${fmt(o.days)} counted days ÷ ${fmt(o.divisor)} assumed accrual divisor.`,items:[['Worked days',o.days],['Accrued days',v]]};break}
    case 'separation':{let v=o.wage*o.factor*o.years/26;result={title:'Illustrative provision only',value:cash(v),detail:`${cash(o.wage)} × ${fmt(o.factor)} days ÷ 26 × ${fmt(o.years)} assumed years; not a statutory separation payable.`,items:[['Monthly base',o.wage],['Modelled amount',v]]};break}
  }
  view.calcResults=result;render()
}
function renderPlanner(){const items=state.tasks.slice().sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));return `<div class="eyebrow">SELF-MANAGED COMPLIANCE PLANNER</div><h1 class="heading">Action Planner</h1><p class="subhead">Track your own follow-up tasks and export calendar reminders. Due dates must be entered by you.</p><div class="stats">${stat('Total tasks',state.tasks.length,'📋')}${stat('Pending',state.tasks.filter(t=>!t.done).length,'⏳')}${stat('Completed',state.tasks.filter(t=>t.done).length,'✔')}${stat('Due soon',state.tasks.filter(t=>!t.done&&t.due&&new Date(t.due+'T00:00:00')<new Date(Date.now()+7*86400000)).length,'📅')}</div><div class="split"><div><div class="card"><h3>Your planned actions</h3>${items.length?items.map(t=>`<div class="list-row" style="align-items:flex-start"><input type="checkbox" class="check" data-action="task-toggle" data-id="${att(t.id)}" ${t.done?'checked':''} style="margin-top:2px"><div class="body"><b style="${t.done?'text-decoration:line-through;opacity:.6':''}">${esc(t.title)}</b><small>${t.due?'Review date: '+dateLabel(t.due):'No review date set'} ${t.notes?' · '+esc(t.notes):''}</small></div><button class="icon-btn" data-action="task-remove" data-id="${att(t.id)}" title="Remove task">${icon('close')}</button></div>`).join(''):'<div class="empty">No tasks yet. Add your first action using the form.</div>'}</div><div class="actions" style="margin-top:15px"><button class="btn secondary" data-action="export-ics">${icon('download')} Export calendar (.ics)</button><button class="btn secondary" data-action="export-planner">${icon('download')} Export Excel report</button></div></div><aside><div class="card"><h3>Create a review task</h3><div class="field"><label>Task title</label><input class="input" id="task-title" maxlength="140" placeholder="Review wage payment policy"></div><div class="field" style="margin-top:13px"><label>Review date you choose</label><input type="date" class="input" id="task-date"></div><div class="field" style="margin-top:13px"><label>Notes (optional)</label><textarea id="task-notes" style="min-height:100px" placeholder="Team, documents to confirm, sources..."></textarea></div><button class="btn" data-action="task-add" style="margin-top:15px">Add task ${icon('arrow')}</button></div><div class="banner warn" style="margin-top:15px"><b>Important</b><p>This is a personal planning tool, not a statutory filing calendar. The app will not invent deadlines or send background notifications. Calendar exports are manual.</p></div></aside></div>`}
function renderDocuments(){const r=view.docResult;return `<div class="eyebrow">ON-DEVICE EDUCATIONAL DOCUMENT SCREENING</div><h1 class="heading">Document Review Studio</h1><p class="subhead">Scan selected TXT, DOCX or text-extractable PDF documents for topics that deserve further legal review.</p><div class="split" style="margin-top:24px"><div><div class="card"><h3>Review a document</h3><p>Analysis runs within the local Windows application. No document is automatically sent to an external AI service.</p><div style="border:1.5px dashed var(--border);border-radius:17px;padding:33px;text-align:center;background:var(--panel2)"><div style="font-size:32px;margin-bottom:11px">📄</div><label for="doc-file" style="display:block;font-size:14px;font-weight:750;margin-bottom:9px">Choose a file to screen</label><input type="file" id="doc-file" accept=".txt,.docx,.pdf" style="max-width:100%;font-size:12px"><div class="muted tiny" style="margin-top:10px">TXT · DOCX · Text PDF · 5 MB maximum</div></div><div class="actions" style="margin-top:15px"><button class="btn" data-action="scan-doc">${icon('search')} Analyse selected file</button><span id="doc-working" class="muted tiny"></span></div></div>${r?`<div class="card" style="margin-top:18px"><div class="kicker">EDUCATIONAL SCAN RESULTS</div><h3 style="margin:12px 0">${esc(r.filename)}</h3><p>${fmt(r.characters)} readable characters extracted.</p><div class="grid-2">${r.findings.map(f=>`<div class="case"><div class="actions"><b>${esc(f.topic)}</b><span class="pill" style="color:${f.detected?'var(--gold)':'var(--muted)'}">${f.detected?'Term detected':'Not detected'}</span></div><p>${esc(f.guidance)}</p></div>`).join('')}</div><div class="banner warn" style="margin-top:16px"><p>${esc(r.notice)}</p></div><div class="actions" style="margin-top:15px"><button class="btn secondary" data-action="export-doc">${icon('download')} Download review Excel</button><button class="btn ghost" data-action="print">${icon('print')} Print / PDF</button></div></div>`:''}</div><aside><div class="card"><h3>What this analysis checks</h3>${[['Payment','Wage periods, salary, deductions'],['Employment','Contract, notice, separation'],['Social protection','EPF, ESI, gratuity, maternity'],['Workplace safety','Health, accidents, hazards'],['Hours & leave','Shifts, holiday and overtime']].map(([a,b])=>`<div class="list-row"><div class="body"><b>${a}</b><small>${b}</small></div></div>`).join('')}</div><div class="banner warn" style="margin-top:15px"><b>No compliance verdict</b><p>Keyword detection cannot determine whether a policy or employment contract is lawful. Scanned PDFs and certain font-encoded PDFs require OCR or advanced extraction not provided here.</p></div></aside></div>`}
function renderReports(){const best=state.scores.length?Math.round(Math.max(...state.scores.map(s=>100*s.correct/s.total))):0;const ok=state.completed.length>=16&&best>=70;
 if(view.cert){return `<div class="actions no-print" style="margin-bottom:20px"><button class="btn ghost" data-action="cert-back">${icon('back')} Back to reports</button><button class="btn" data-action="print">${icon('print')} Print / Save as PDF</button></div><div class="report-paper" style="background:linear-gradient(155deg,var(--panel),var(--panel2));text-align:center;min-height:550px;padding:55px 35px;border:5px double color-mix(in srgb,var(--gold) 42%,var(--border));margin:0 auto;max-width:1000px"><div style="font-size:42px">⚖️</div><div class="eyebrow">LabourCode Pro 3.0</div><h1 style="font-size:39px;letter-spacing:-1px;margin:27px 0 13px">Certificate of Self-Study Completion</h1><p>This educational milestone acknowledges that the learner has completed the required study objectives within</p><h2 style="font-size:27px;margin:32px 0">LabourCode Pro — India's Four Labour Codes</h2><div class="big-number" style="font-size:27px;color:var(--teal)">${state.completed.length} completed lessons · ${best}% best quiz result</div><p>Issued ${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</p><div class="hr-line"></div><p style="font-weight:700">Developed by Avinash Ekka</p><p class="footnote">Non-accredited self-study acknowledgment only. This is not a government, legal, professional or recognised training certification, and does not attest legal competence.</p></div>`}
 return `<div class="eyebrow">LEARNING INSIGHTS & EXPORTS</div><h1 class="heading">Reports & Progress</h1><p class="subhead">Inspect your educational achievements and download spreadsheet or printable reports.</p><div class="stats">${stat('Learning completion',percentDone()+'%','📊')}${stat('Lessons completed',state.completed.length,'📖')}${stat('Practice attempts',state.scores.length,'🧠')}${stat('Completed checks',state.checkmarks.length,'✅')}</div><div class="split"><div><div class="card"><h3>Learning overview</h3>${D.codes.map(c=>`<div style="margin:14px 0"><div class="actions" style="justify-content:space-between;margin-bottom:8px"><b>${esc(ALL[c.id])}</b><small class="muted">${completedFor(c.id)}/8 lessons</small></div>${meter(completedFor(c.id)/8*100)}</div>`).join('')}<div class="hr-line"></div><h3>Assessment record</h3>${state.scores.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Assessment</th><th>Correct</th><th>Score</th></tr></thead><tbody>${state.scores.slice(-12).reverse().map(s=>`<tr><td>${esc(s.date)}</td><td>${esc(s.mode)}</td><td>${s.correct}/${s.total}</td><td>${Math.round(s.correct/s.total*100)}%</td></tr>`).join('')}</tbody></table></div>`:'<p>Complete a test to see your results.</p>'}</div><div class="actions" style="margin-top:18px"><button class="btn" data-action="export-progress">${icon('download')} Export learning Excel</button><button class="btn secondary" data-action="export-compliance">${icon('download')} Compliance Excel</button><button class="btn ghost" data-action="print">${icon('print')} Print / PDF</button></div></div><aside><div class="card"><h3>Certificate status</h3><div style="font-size:39px;margin:14px 0">${ok?'🏅':'🔐'}</div><p>${ok?'The non-accredited certificate milestone is unlocked.':'To unlock, finish at least 16 lessons and score 70% on a quiz.'}</p><div class="muted tiny">Lessons: ${state.completed.length}/16 · Best score: ${best}%/70%</div><button class="btn" style="margin-top:17px" data-action="certificate" ${ok?'':'disabled'}>${icon('award')} View learning certificate</button></div><div class="card" style="margin-top:17px"><h3>Data and privacy</h3><p>Progress and review flags are saved within private Android app storage. No account is required. Export a copy at any time.</p><button class="btn secondary small" data-action="export-json">${icon('download')} Back up progress (JSON)</button></div></aside></div>`}
function renderSettings(){return `<div class="eyebrow">PERSONALISE YOUR EXPERIENCE</div><h1 class="heading">Settings</h1><p class="subhead">Adapt the learning environment to your job role, preferred appearance and reading style.</p><div class="split" style="margin-top:24px"><div><div class="card"><h3>Personal learning profile</h3><p>Recommended content is shown first on your dashboard; the complete library remains accessible.</p><div class="field"><label>How are you using LabourCode Pro?</label><select id="setting-role">${Object.entries(roles).map(([k,t])=>`<option value="${k}" ${k===state.role?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-row" style="margin-top:16px"><div class="field"><label>Appearance</label><select id="setting-theme"><option value="dark" ${state.theme==='dark'?'selected':''}>Midnight enterprise (dark)</option><option value="light" ${state.theme==='light'?'selected':''}>Professional white (light)</option></select></div><div class="field"><label>Interface language</label><select id="setting-lang"><option value="en">English</option><option value="hi" ${state.language==='hi'?'selected':''}>Hindi support (limited beta)</option></select></div></div><div class="field" style="margin-top:15px"><label>Text scaling</label><select id="setting-font"><option value="1" ${state.fontScale===1?'selected':''}>Regular</option><option value="1.10" ${state.fontScale===1.1?'selected':''}>Large (+10%)</option><option value="1.20" ${state.fontScale===1.2?'selected':''}>Extra large (+20%)</option><option value="1.40" ${state.fontScale===1.4?'selected':''}>Maximum (+40%)</option></select></div><button class="btn" style="margin-top:18px" data-action="save-settings">Save preferences ${icon('check')}</button></div><div class="card" style="margin-top:18px"><h3>Storage & privacy</h3><p>Local learning progress, quiz scores, saved terms, checklists and tasks are stored in your Android private app storage.</p><p><b>Directory:</b> <code>%APPDATA%\LabourCodePro\progress.json</code> on typical Windows systems.</p><p>Document review is local. Cloud tutor mode is off unless enabled by you; your optional backend token is held only in app memory.</p><div class="actions"><button class="btn secondary" data-action="export-json">Back up progress</button><button class="btn ghost" data-action="import-json">Restore from backup</button><input type="file" id="import-json-file" accept=".json" hidden><button class="btn danger" data-action="clear-progress">Clear local progress</button></div></div></div><aside><div class="card"><img src="assets/logo.png" alt="App logo" width="70" height="70" style="object-fit:cover;border-radius:16px"><h3 style="margin-top:16px">LabourCode Pro 3.0</h3><p>Windows Edition · Portable local application</p><p>Developed by Avinash Ekka</p><div class="hr-line"></div><h4>Content review date</h4><p>${dateLabel(D.verified)}</p><h4>Source and legal caution</h4><p>Educational, non-government content. Not a substitute for a lawyer, payroll provider or compliance auditor.</p>${extlink(P.official,'Ministry official source portal')}<div class="hr-line"></div><button class="btn ghost" data-action="exit">${icon('exit')} Exit app</button></div></aside></div>`}
function renderView(){switch(view.route){case 'home':return renderHome();case 'fullacts':return renderFullActs();case 'actreader':return renderActReader();case 'visuals':return renderInfographics();case 'learn':return renderLearn();case 'module':return renderModule();case 'lesson':return renderLesson();case 'academy':return renderAcademy();case 'quiz':return renderQuizLanding();case 'quizplay':return renderQuizPlay();case 'flashcards':return renderFlashcards();case 'matching':return renderMatching();case 'search':return renderSearch();case 'advisor':return renderAdvisor();case 'glossary':return renderGlossary();case 'compare':return renderCompare();case 'updates':return renderUpdates();case 'compliance':return renderCompliance();case 'calculator':return renderCalculator();case 'planner':return renderPlanner();case 'documents':return renderDocuments();case 'reports':return renderReports();case 'settings':return renderSettings();default:return renderHome()}}
function popup(title,inner){modalRoot.innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${att(title)}"><div class="actions" style="justify-content:space-between;margin-bottom:15px"><span class="kicker">INTERACTIVE LEGAL REFERENCE</span><button class="icon-btn" data-action="modal-close" title="Close">${icon('close')}</button></div><h2>${esc(title)}</h2>${inner}<div style="margin-top:22px"><button class="btn secondary" data-action="modal-close">Close</button></div></div></div>`}
function showTerm(term){const t=D.glossary.find(x=>x.term===term);if(!t)return;popup(t.term,`<p style="font-size:15px;color:var(--ink)">${esc(t.definition)}</p><div class="case"><b>Practical example</b><p>${esc(t.example)}</p></div>${hindiHints[t.term]?`<p><b>Simple Hindi equivalent (not a statutory translation):</b> ${esc(hindiHints[t.term])}</p>`:''}<p><b>Relevant area:</b> ${t.code==='all'?'All four Codes':esc(ALL[t.code]||t.code)}</p><p>For statutory meaning, confirm the specific Code definition and its exceptions. Words may have distinct meanings across Codes.</p>`)}
function showCase(code,idx){let c=C[code],v=c?.cases[idx];if(!v)return;popup(v.title,`<span class="pill">${esc(ALL[code])}</span><h3 style="margin-top:17px">Situation</h3><p>${esc(v.situation)}</p><h3>Educational analysis</h3><p>${esc(v.analysis)}</p><div class="banner good"><b>Study tip</b><p>${esc(v.tip)}</p></div><p>${extlink(c.source,'Check original statutory Code')}</p>`)}
function downloadBlob(blob,name){if(window.AndroidBridge){const fr=new FileReader();fr.onload=()=>AndroidBridge.saveBase64(name,blob.type||'application/octet-stream',String(fr.result).split(',')[1]||'');fr.readAsDataURL(blob);return}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),12000)}
async function exportXlsx(sheet,rows,name){if(window.AndroidBridge){AndroidBridge.exportXlsx(name,JSON.stringify({sheet,rows:rows.map(r=>r.map(x=>String(x??'')))}));toast('Exporting Excel file to Downloads');return}try{const res=await fetch('/api/export/xlsx',{method:'POST',headers:{'Content-Type':'application/json','X-LCP-Token':appToken},body:JSON.stringify({sheet,rows:rows.map(r=>r.map(x=>String(x??'')))})});if(!res.ok)throw Error('Could not prepare spreadsheet');downloadBlob(await res.blob(),name);toast('Excel spreadsheet exported')}catch(e){toast('Export failed: '+e.message)}}
function exportProgress(){const rows=[['LabourCode Pro — Learning Progress'],['Code','Lesson','Status','Reviewed']];for(let c of D.codes){for(let l of c.lessons)rows.push([c.name,l.title,state.completed.includes(l.id)?'Completed':'Pending',l.lastReviewed])}rows.push([],['Date','Quiz type','Code','Correct','Total','Percentage']);for(let s of state.scores)rows.push([s.date,s.mode,s.code,s.correct,s.total,Math.round(s.correct/s.total*100)+'%']);return exportXlsx('Learning Progress',rows,'LabourCodePro_Learning_Progress.xlsx')}
function exportCompliance(){let rows=[['Code','Review point','Explanation','Indicative marker','Reviewed','State']];P.checklist.forEach((x,i)=>rows.push([ALL[x.code],x.title,x.detail,x.threshold==='all'?'Check separately':x.threshold,state.checkmarks.includes(i)?'Yes':'No',state.preferredState]));return exportXlsx('Compliance Review',rows,'LabourCodePro_Compliance_Review.xlsx')}
function exportPlanner(){let rows=[['Task','User-selected review date','Notes','Completed']];state.tasks.forEach(t=>rows.push([t.title,t.due,t.notes,t.done?'Yes':'No']));return exportXlsx('Personal Planner',rows,'LabourCodePro_Action_Planner.xlsx')}
function exportDoc(){let r=view.docResult;if(!r){toast('Analyse a file first');return};const rows=[['Document','Topic','Keyword detected','Suggested follow-up']];r.findings.forEach(x=>rows.push([r.filename,x.topic,x.detected?'Yes':'No',x.guidance]));rows.push([],['Note',r.notice]);return exportXlsx('Document Review',rows,'LabourCodePro_Document_Review.xlsx')}
function exportICS(){const escapeICS=s=>String(s||'').replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\n/g,'\\n');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//LabourCode Pro//Personal Review Planner//EN','CALSCALE:GREGORIAN'];let included=0;for(let t of state.tasks){if(!/^\d{4}-\d{2}-\d{2}$/.test(t.due||''))continue;let start=t.due.replace(/-/g,'');let next=new Date(t.due+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+1);let end=next.toISOString().slice(0,10).replace(/-/g,'');lines.push('BEGIN:VEVENT','UID:'+t.id+'@labourcodepro.local','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;VALUE=DATE:'+start,'DTEND;VALUE=DATE:'+end,'SUMMARY:'+escapeICS(t.title),'DESCRIPTION:'+escapeICS((t.notes||'')+' | User-defined review reminder; not a statutory due date.'),'END:VEVENT');included++}lines.push('END:VCALENDAR');if(!included){toast('Add a task with a review date first');return}downloadBlob(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar'}),'LabourCodePro_Review_Planner.ics');toast('Calendar file exported')}
function exportJSON(){downloadBlob(new Blob([JSON.stringify({application:'LabourCode Pro Android',version:'1.0',saved:new Date().toISOString(),state},null,2)],{type:'application/json'}),'LabourCodePro_Progress_Backup.json');toast('Progress backup downloaded')}
function handleSpeak(lessonID){let l=allLessons.find(x=>x.id===lessonID);if(!l)return;if(!('speechSynthesis' in window)){toast('Read aloud is not available in this browser');return}speechSynthesis.cancel();let msg=new SpeechSynthesisUtterance([l.title,l.summary,...l.paragraphs,l.example].join('. '));msg.lang=state.language==='hi'?'hi-IN':'en-IN';msg.rate=.92;speechSynthesis.speak(msg);toast('Read aloud started')}
async function analyzeDoc(){if(window.AndroidBridge){const file=document.getElementById('doc-file')?.files?.[0];if(!file){toast('Choose a TXT, DOCX or PDF document');return}if(file.size>5*1024*1024){toast('File exceeds 5 MB');return}const reader=new FileReader();reader.onload=()=>{const b64=String(reader.result).split(',')[1]||'';AndroidBridge.analyzeDocument(file.name,b64);toast('Reviewing document on device…')};reader.readAsDataURL(file);return}let el=document.getElementById('doc-file');if(!el?.files?.length){toast('Choose a TXT, DOCX or PDF file');return}let file=el.files[0];if(file.size>5*1024*1024){toast('File exceeds the 5 MB limit');return}let status=document.getElementById('doc-working');if(status)status.textContent='Analysing locally…';try{let form=new FormData();form.append('file',file);let res=await fetch('/api/analyze',{method:'POST',headers:{'X-LCP-Token':appToken},body:form});let data=await res.json();if(!res.ok)throw Error(data.error||'Review failed');view.docResult=data;render();toast('Local screening complete')}catch(e){if(status)status.textContent='';toast('Review unavailable: '+e.message)}}
async function askTutor(){let input=document.getElementById('tutor-question');let question=(input?.value||'').trim();if(question.length<3){toast('Enter a question first');return};view.tutorAsk=question;
 if(window.AndroidBridge && view.tutorMode!=='offline'){view.tutorAnswer={cloud:true,question,error:'Cloud AI requires a separately configured, secure HTTPS backend. Offline legal tutoring is available now.'};render();return}
 if(view.tutorMode==='offline'){view.tutorAnswer={cloud:false,question,results:answerOffline(question)};addStudy();markSaved();render();return}
 let endpoint=document.getElementById('cloud-endpoint')?.value.trim()||'';
 cloudBearer=document.getElementById('cloud-token')?.value||'';state.cloudEndpoint=endpoint;markSaved();
 view.tutorAnswer={cloud:true,question,answer:'Connecting to your configured secure backend…'};render();
 try{let excerpts=answerOffline(question).map(r=>`${r.name}: ${r.description}`).join('\n').slice(0,6000);let res=await fetch('/api/cloud',{method:'POST',headers:{'Content-Type':'application/json','X-LCP-Token':appToken},body:JSON.stringify({endpoint,bearer:cloudBearer,question,context:excerpts,locale:state.language})});let a=await res.json();if(!res.ok)throw Error(a.error||'Cloud request failed');view.tutorAnswer={cloud:true,question,answer:a.answer||'No response received'};render()}catch(e){view.tutorAnswer={cloud:true,question,error:e.message};render()}
}
function applySettings(){state.role=document.getElementById('setting-role').value;state.theme=document.getElementById('setting-theme').value;state.language=document.getElementById('setting-lang').value;state.fontScale=num(document.getElementById('setting-font').value)||1;markSaved();render();toast('Preferences saved')}
function applyProfile(){state.preferredState=document.getElementById('profile-state').value;state.companyGov=document.getElementById('profile-gov').value;state.companyIndustry=document.getElementById('profile-industry').value;state.companyHeadcount=Math.max(0,Math.floor(num(document.getElementById('company-headcount').value)));markSaved();render();toast('Review profile saved (not a legal applicability determination)')}
function addTask(){let title=document.getElementById('task-title')?.value.trim().slice(0,140);let due=document.getElementById('task-date')?.value;let notes=document.getElementById('task-notes')?.value.trim().slice(0,600);if(!title){toast('Provide a task title');return}state.tasks.push({id:'t'+Date.now().toString(36)+Math.floor(Math.random()*10000),title,due,notes,done:false});markSaved();render();toast('Personal task added')}


// V3 legal library & premium dashboard. The complete statutory text is the original PDF.
NAV[0].items.splice(1,0,['fullacts','Full Legal Texts','documents']);
NAV[0].items.splice(4,0,['visuals','Interactive Visuals','chart']);
const ACTS_META={
 wages:{name:'Code on Wages, 2019',short:'WAGES',act:'29 of 2019',pages:29,note:'Minimum wages · wage periods · overtime · payment of bonus',color:'#078c83'},
 industrial:{name:'Industrial Relations Code, 2020',short:'RELATIONS',act:'35 of 2020',pages:56,note:'Trade unions · standing orders · industrial dispute resolution',color:'#7563d0'},
 security:{name:'Code on Social Security, 2020',short:'SECURITY',act:'36 of 2020',pages:116,note:'PF · ESI · gratuity · maternity · gig and platform workers',color:'#ca873a'},
 osh:{name:'Occupational Safety, Health and Working Conditions Code, 2020',short:'WORKPLACE',act:'37 of 2020',pages:86,note:'Workplace safety · welfare · working hours · contract labour',color:'#d46671'}
};
let actStatus={},actLoading='',actDownloadError='',importTarget='';
async function refreshActStatus(silent=false){
 if(window.AndroidBridge){try{actStatus=JSON.parse(AndroidBridge.actStatus());if(!silent&&['fullacts','actreader','home'].includes(view.route))render()}catch(e){actDownloadError=e.message}return}
 try{const response=await fetch('/api/act/status',{headers:{'X-LCP-Token':appToken}});if(!response.ok)throw Error('Could not read full-text library status');const j=await response.json();actStatus=j.acts||{};if(!silent&&['fullacts','actreader','home'].includes(view.route))render()}
 catch(e){actDownloadError=e.message;if(!silent&&['fullacts','actreader'].includes(view.route))render()}
}
async function downloadAct(id){
 if(window.AndroidBridge){toast('Select an authentic Gazette PDF stored on your device');AndroidBridge.importAct(id);return}
 if(!ACTS_META[id]||actLoading)return;
 actLoading=id;actDownloadError='';render();
 try{
   const r=await fetch('/api/act/download?code='+encodeURIComponent(id),{method:'POST',headers:{'X-LCP-Token':appToken}});
   const j=await r.json();if(!r.ok)throw Error(j.error||'Official PDF download failed');
   await refreshActStatus(true);toast('Complete original PDF saved to this PC');
 }catch(e){actDownloadError=e.message;toast('Download could not finish')}
 finally{actLoading='';render()}
}
async function downloadAllActs(){
 if(actLoading)return;
 for(const id of Object.keys(ACTS_META)){
   if(!actStatus[id]?.cached)await downloadAct(id);
 }
}
function pdfUrl(id){return window.AndroidBridge?'#offline-android-reader':'/api/act/pdf?code='+encodeURIComponent(id)+'&session='+encodeURIComponent(appToken)}
