function renderActReader(){
 const id=ACTS_META[view.code]?view.code:'wages',c=C[id],meta=ACTS_META[id],status=actStatus[id]||{};
 const cases=c.cases.slice(0,3);
 return `<div class="reader-intro"><button class="btn ghost small" data-go="fullacts">${icon('back')} All four Codes</button><div class="reader-name"><div class="eyebrow">ORIGINAL GAZETTE TEXT · ${meta.act}</div><h1 class="heading">${esc(meta.name)}</h1><p class="subhead">Entire published Code · approximately ${meta.pages} PDF pages · original Gazette publication</p></div><div class="reader-actions"><button class="btn secondary" data-go="module" data-code="${id}">${icon('learn')} Study guide</button><a class="btn ghost" href="${att(status.source||c.source)}" target="_blank" rel="noopener noreferrer">Official site ↗</a></div></div>
 ${actDownloadError?`<div class="banner warn"><b>Source unavailable</b><p>${esc(actDownloadError)}</p></div>`:''}
 ${status.cached?`<div class="fulltext-badge"><span>● ${status.imported?'User-imported document; verify authenticity':'Original official document stored locally'}</span><span>${Math.round((status.bytes||0)/1024)} KB · SHA-256: ${esc((status.sha256||'').slice(0,18))}…</span><button class="btn ghost small" data-action="print-law">Print or save a copy</button></div><div class="reader-grid"><div class="pdf-panel"><iframe title="Complete full legal text of ${att(meta.name)}" class="law-pdf" src="${pdfUrl(id)}#toolbar=1&navpanes=1&view=FitH" loading="eager"></iframe></div>${renderReaderAside(id,c,cases)}</div>`:
 `<section class="pdf-empty"><div class="pdf-empty-icon">${icon('documents',48)}</div><span class="eyebrow">GET THE COMPLETE ORIGINAL TEXT</span><h2>${esc(meta.name)}</h2><p>This app never substitutes a summary for the statute. This exact official Gazette must be stored to show the complete primary text. You can add it through the integrated document facility; no external website needs to be opened.</p><div class="actions"><button class="btn" data-action="download-act" data-code="${id}" ${actLoading?'disabled':''}>${actLoading===id?'Downloading source…':'Download complete Code ('+meta.pages+' pages)'} ${icon('download')}</button><a href="${att(meta.source||c.source)}" target="_blank" rel="noopener noreferrer" class="btn ghost">Read at government source ↗</a></div><div class="actions import-option"><button class="btn ghost" data-action="import-act" data-code="${id}">Or import a PDF you downloaded from the government website</button></div><div class="download-notice">The first download requires an internet connection. Network filters and government website availability may affect access.</div></section>
 <div class="reader-grid-nopdf">${renderReaderAside(id,c,cases)}</div>`}
 <div class="disclosure-line">${icon('bell')} The original enactment PDF is not a guarantee of the law as amended or brought into force today. Review commencement notifications, operative Rules, amendments and jurisdiction-specific requirements.</div>`
}
function renderReaderAside(id,c,cases){return `<aside class="reader-side"><div class="side-guide"><div class="eyebrow">UNDERSTAND THE PROVISIONS</div><h3>Plain-language companion</h3><p>Use the native full-text reader above; these learning notes are separate editorial content.</p><button class="btn secondary" data-go="module" data-code="${id}">Explore 8 guided lessons ${icon('arrow')}</button></div>
 <div class="side-guide"><div class="eyebrow">REAL-WORLD EXAMPLES</div>${cases.map((v,i)=>`<button class="mini-case" data-action="case" data-code="${id}" data-index="${i}"><span>CASE 0${i+1}</span><b>${esc(v.title)}</b><small>Situation, analysis and study tip ${icon('arrow')}</small></button>`).join('')}</div>
 <div class="side-guide"><div class="eyebrow">TAP A LEGAL TERM</div><div class="term-cloud">${D.glossary.filter(x=>x.code===id || x.code==='all').slice(0,11).map(t=>`<button data-action="term" data-term="${att(t.term)}">${esc(t.term)}</button>`).join('')}</div><p>These definitions are educational; the precise statutory meaning depends on the Code.</p></div>
 <div class="side-guide"><div class="eyebrow">TEXT SEARCH & VIEW</div><p><b>The native reader offers page controls and zoom. In-app statutory text search is planned for a future Android update.</p><p>Read and search the complete official document inside this workspace, without opening external pages.</p></div></aside>`}
function renderInfographics(){
 let excluded=Math.max(0,Math.min(90,Number(view.demoExcluded??60))),total=60000,base=100-excluded,additional=Math.max(0,excluded-50),illustrative=(base+additional)*total/100;
 return `<div class="eyebrow">INTERACTIVE CONCEPT STUDIO</div><h1 class="heading">See the four Codes in action</h1><p class="subhead">Explore legal concepts through original infographics and illustrative, non-binding calculations. Select any Code to read the exact legal text.</p>
 <div class="visual-hero"><div><span>THE LABOUR FRAMEWORK</span><h2>29 former central laws organised into 4 Codes</h2><p>Each Code addresses a different part of employment relationships. Their applicability and detailed obligations require the actual legislation and subordinate Rules.</p><button class="btn" data-go="fullacts">Read primary sources ${icon('arrow')}</button></div><div class="visual-wheel"><div class="center-disc">4 <small>Labour Codes</small></div>${D.codes.map((c,i)=>`<button class="wheel-arm arm-${i}" data-go="actreader" data-code="${c.id}" aria-label="Read ${att(c.name)}">${['₹','IR','SS','OSH'][i]}</button>`).join('')}</div></div>
 <div class="grid-2 visual-panels"><section class="card visual-panel"><div class="eyebrow">01 · WAGE COMPOSITION</div><h2>How the 50% exclusion example works</h2><p>Move the slider to explore a simplified illustration of the wage-definition add-back idea. This does not classify actual payroll components or determine PF/gratuity liability.</p><div class="range-row"><label for="viz-exclusion">Assumed excluded remuneration</label><strong id="viz-exclusion-text">${excluded}%</strong></div><input type="range" id="viz-exclusion" min="0" max="90" step="5" value="${excluded}" aria-label="Assumed excluded remuneration percentage"/>
 <div class="composition"><div class="comp-included" id="viz-included-bar" style="width:${base}%">${base>=15?base+'%':''}</div><div class="comp-excluded" style="width:${excluded}%" id="viz-excluded-bar">${excluded>=15?excluded+'%':''}</div></div><div class="comp-legend"><span><i class="key included"></i> Included components (assumed)</span><span><i class="key excluded"></i> Excluded components (assumed)</span></div><div class="formula-result"><small>Illustrative wage base after excess-exclusion add-back</small><strong id="viz-result">${cash(illustrative)}</strong><span id="viz-note">${additional?'Add-back: '+additional+'% of total assumed remuneration':'No excess-exclusion add-back in this model'}</span></div><button class="btn ghost" data-go="actreader" data-code="wages">Read Code on Wages, section 2(y) ${icon('arrow')}</button></section>
 <section class="card visual-panel"><div class="eyebrow">02 · APPLICATION & PROCESS</div><h2>From question to provision</h2><p>A structured pathway for interpreting a real workplace issue.</p><div class="process-flow"><div><b>01</b><span>Identify the issue</span><small>Wages, relations, social security or OSH</small></div><div><b>02</b><span>Read the statutory definition</span><small>Term, scope, exceptions and cross-references</small></div><div><b>03</b><span>Check operative Rules</span><small>State, appropriate government, commencement</small></div><div><b>04</b><span>Test on realistic examples</span><small>Review with experienced HR/legal counsel</small></div></div></section></div>
 <div class="section-head"><h2>Browse interactive Code infographics</h2></div><div class="law-grid viz-code-grid">${D.codes.map((c,i)=>`<button class="viz-code" data-go="actreader" data-code="${c.id}"><img src="assets/editorial_${c.id}.webp" alt="${att(c.name)}"/><div><span>0${i+1} / ACT ${ACTS_META[c.id].act}</span><h3>${esc(c.name)}</h3><p>${esc(ACTS_META[c.id].note)}</p><b>Read complete legal text ${icon('arrow')}</b></div></button>`).join('')}</div>`
}

// Local manual import is an escape hatch for restricted corporate networks.
document.body.insertAdjacentHTML('beforeend','<input id="manual-act-upload" type="file" accept="application/pdf,.pdf" hidden aria-label="Select official Gazette PDF">');
document.getElementById('manual-act-upload').addEventListener('change',async e=>{
 const f=e.target.files?.[0],id=importTarget;if(!f||!ACTS_META[id])return;
 if(window.AndroidBridge){AndroidBridge.importAct(id);return}if(!confirm('Import the document as '+ACTS_META[id].name+'? The app checks PDF integrity but cannot verify legal authenticity or that this is the correct Code.'))return;
 actLoading=id;actDownloadError='';render();
 try{let fd=new FormData();fd.append('pdf',f);const r=await fetch('/api/act/import?code='+encodeURIComponent(id),{method:'POST',headers:{'X-LCP-Token':appToken},body:fd});let j=await r.json();if(!r.ok)throw Error(j.error||'Could not import PDF');await refreshActStatus(true);toast('Local document imported—verify against official Gazette')}
 catch(err){actDownloadError=err.message}finally{actLoading='';e.target.value='';render()}
});
// Separate captured actions from the existing module interactions.
app.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;
 const a=el.dataset.action;
 if(a==='download-act'){e.stopImmediatePropagation();downloadAct(el.dataset.code)}
 if(a==='download-all-acts'){e.stopImmediatePropagation();downloadAllActs()}
 if(a==='import-act'){e.stopImmediatePropagation();importTarget=el.dataset.code;if(window.AndroidBridge)AndroidBridge.importAct(importTarget);else document.getElementById('manual-act-upload')?.click()}
 if(a==='print-law'){e.stopImmediatePropagation();if(window.AndroidBridge)AndroidBridge.openAct(view.code);else window.open(pdfUrl(view.code),'_blank','noopener')}
},true);
app.addEventListener('input',e=>{
 if(e.target.id!=='viz-exclusion')return;
 const v=Math.min(90,Math.max(0,Number(e.target.value)||0));view.demoExcluded=v;
 const base=100-v;const add=Math.max(0,v-50),wage=60000*(base+add)/100;
 const set=(id,val)=>{const el=document.getElementById(id);if(el)el.textContent=val};
 set('viz-exclusion-text',v+'%');set('viz-result',cash(wage));set('viz-note',add?`Illustrative add-back: ${add}% of total remuneration`:'No excess-exclusion add-back in this model');
 const a=document.getElementById('viz-included-bar'),b=document.getElementById('viz-excluded-bar');
 if(a){a.style.width=base+'%';a.textContent=base>=15?base+'%':''}
 if(b){b.style.width=v+'%';b.textContent=v>=15?v+'%':''}
});
// Refresh when views are entered, and once initial session loading has settled.
app.addEventListener('click',e=>{if(e.target.closest('[data-go="fullacts"],[data-go="actreader"],[data-go="home"]'))setTimeout(()=>refreshActStatus(true).then(()=>{if(['fullacts','actreader','home'].includes(view.route))render()}),30)});
setTimeout(()=>refreshActStatus().catch(()=>{}),900);

app.addEventListener('click',e=>{
 const target=e.target.closest('[data-action],[data-go]');if(!target||target.disabled)return;
 const route=target.dataset.go;
 if(route){if(route==='matching'){startMatching();return}if(route==='flashcards'){view.flashIdx=0;view.flashRevealed=false}go(route,target.dataset.code,target.dataset.lesson);return}
 const ac=target.dataset.action,id=target.dataset.id,code=target.dataset.code,index=num(target.dataset.index);
 switch(ac){
 case 'theme':state.theme=state.theme==='dark'?'light':'dark';markSaved();render();break;
 case 'term':showTerm(target.dataset.term);break;
 case 'case':showCase(code,index);break;
 case 'complete':if(!state.completed.includes(id)){state.completed.push(id);addStudy();toast('Lesson marked complete')}else{toast('Already marked as complete')}markSaved();render();break;
 case 'bookmark':if(state.bookmarks.includes(id))state.bookmarks=state.bookmarks.filter(x=>x!==id);else state.bookmarks.push(id);markSaved();render();break;
 case 'speak':handleSpeak(id);break;
 case 'start-quiz':startQuiz(target.dataset.mode,code||'all');break;
 case 'answer':if(!view.quiz||view.quiz.checked)return;view.quiz.selected=index;view.quiz.checked=true;view.quiz.answers.push({question:view.quiz.questions[view.quiz.idx].id,selected:index,correct:index===view.quiz.questions[view.quiz.idx].answer});render();break;
 case 'quiz-next':if(!view.quiz||!view.quiz.checked)return;if(view.quiz.idx>=view.quiz.questions.length-1)finalizeQuiz();else{view.quiz.idx++;view.quiz.selected=null;view.quiz.checked=false;render()}break;
 case 'flash-filter':view.flashFilter=target.dataset.filter;view.flashIdx=0;view.flashRevealed=false;render();break;
 case 'flash-prev':view.flashIdx=Math.max(0,view.flashIdx-1);view.flashRevealed=false;render();break;
 case 'flash-next':view.flashIdx++;view.flashRevealed=false;render();break;
 case 'flash-reveal':view.flashRevealed=true;render();break;
 case 'flash-rate':{let list=view.flashFilter==='due'?dueTerms():D.glossary;let t=list[view.flashIdx%Math.max(1,list.length)];if(!t)return;let days=target.dataset.rate==='easy'?7:target.dataset.rate==='good'?3:1;state.flashcards[t.term]={next:new Date(Date.now()+days*86400000).toISOString(),rating:target.dataset.rate};view.flashIdx=view.flashFilter==='due'?0:view.flashIdx+1;view.flashRevealed=false;addStudy();markSaved();render();break}
 case 'restart-matching':startMatching();break;
 case 'match-term':matching.selectedTerm=target.dataset.term;render();break;
 case 'match-definition':if(!matching.selectedTerm){toast('Select a term on the left first');return}if(matching.selectedTerm===target.dataset.term){matching.matched.push(target.dataset.term);matching.selectedTerm=null;toast('Correct match!')}else{matching.mistakes++;toast('Not quite. Try another definition.')}render();break;
 case 'search-example':view.query=target.dataset.query;go('search');break;
 case 'tutor-example':view.tutorAsk=target.dataset.query;go('advisor');break;
 case 'tutor-mode':view.tutorMode=target.dataset.mode;view.tutorAnswer=null;render();break;
 case 'ask':askTutor();break;
 case 'apply-profile':applyProfile();break;
 case 'check':{let chk=target.checked;const i=index;if(chk&&!state.checkmarks.includes(i))state.checkmarks.push(i);if(!chk)state.checkmarks=state.checkmarks.filter(x=>x!==i);markSaved();render();break}
 case 'calc-tab':view.calculator=target.dataset.tab;view.calcResults=null;render();break;
 case 'calc-reset':view.calcInputs??={};delete view.calcInputs[view.calculator];view.calcResults=null;render();toast('Inputs reset');break;
 case 'calculate':calculate();break;
 case 'task-add':addTask();break;
 case 'task-toggle':{let t=state.tasks.find(x=>x.id===id);if(t)t.done=target.checked;markSaved();render();break}
 case 'task-remove':state.tasks=state.tasks.filter(x=>x.id!==id);markSaved();render();toast('Task removed');break;
 case 'export-ics':exportICS();break;
 case 'export-planner':exportPlanner();break;
 case 'scan-doc':analyzeDoc();break;
 case 'export-doc':exportDoc();break;
 case 'export-progress':exportProgress();break;
 case 'export-compliance':exportCompliance();break;
 case 'export-json':exportJSON();break;
 case 'import-json':document.getElementById('import-json-file')?.click();break;
 case 'save-settings':applySettings();break;
 case 'certificate':view.cert=true;go('reports');view.cert=true;render();break;
 case 'cert-back':view.cert=false;render();break;
 case 'print':if(window.AndroidBridge)AndroidBridge.printCurrent();else window.print();break;
 case 'clear-progress':if(confirm('Delete saved lessons, quizzes, checklist reviews, flashcards, tasks and preferences from this Windows profile? Export a backup first.')){state=defaultState();markSaved();render();toast('Local progress reset')}break;
 case 'exit':if(window.AndroidBridge){AndroidBridge.finishApp();break}if(confirm('Close application?'))fetch('/api/exit',{method:'POST',headers:{'X-LCP-Token':appToken}}).catch(()=>{});break;
 }
});
app.addEventListener('input',e=>{
 let t=e.target;
 if(t.id==='global-search'||t.id==='glossary-search'){
  let pos=t.selectionStart;
  if(t.id==='global-search')view.query=t.value;else view.glossaryQuery=t.value;
  render();let input=document.getElementById(t.id);input?.focus();try{input?.setSelectionRange(pos,pos)}catch(_){}
 }
 if(t.id==='tutor-question')view.tutorAsk=t.value;
 if(t.dataset.calcKey){view.calcInputs??={};view.calcInputs[view.calculator]??={};view.calcInputs[view.calculator][t.dataset.calcKey]=t.value}
});
app.addEventListener('change',e=>{
 let t=e.target;
 if(t.id==='glossary-code'){view.filteredCode=t.value;render()}
 if(t.id==='import-json-file'&&t.files?.[0]){
  let reader=new FileReader();reader.onload=()=>{
   try{let backup=JSON.parse(reader.result);if(backup.application!=='LabourCode Pro Android'||!backup.state||!Array.isArray(backup.state.completed)||!Array.isArray(backup.state.scores))throw Error('Not a valid LabourCode Pro Android backup');if(!confirm('Replace this PC’s current progress with the selected backup?'))return;
    const incoming=backup.state;state={...defaultState(),...incoming,completed:incoming.completed.filter(x=>allLessons.some(l=>l.id===x)),bookmarks:Array.isArray(incoming.bookmarks)?incoming.bookmarks:[],checkmarks:Array.isArray(incoming.checkmarks)?incoming.checkmarks.filter(x=>Number.isInteger(x)&&x>=0&&x<P.checklist.length):[],tasks:Array.isArray(incoming.tasks)?incoming.tasks.slice(0,500):[],scores:incoming.scores.slice(0,150)};markSaved();render();toast('Progress restored');
   }catch(err){toast('Could not restore: '+err.message)}
  };reader.readAsText(t.files[0]);
 }
});
modalRoot.addEventListener('click',e=>{if(e.target.id==='modal-backdrop'||e.target.closest('[data-action="modal-close"]'))modalRoot.innerHTML=''});
document.addEventListener('keydown',e=>{if(e.key==='Escape')modalRoot.innerHTML=''});
if(!window.AndroidBridge)setInterval(()=>{if(appToken)fetch('/api/ping',{headers:{'X-LCP-Token':appToken}}).catch(()=>{})},25000);
setInterval(()=>{if(view.route==='quizplay'&&view.quiz?.endAt&&!view.quiz.finished){let left=Math.max(0,Math.round((view.quiz.endAt-Date.now())/1000));let el=document.getElementById('countdown');if(el)el.textContent=clock(left);if(!left){finalizeQuiz();toast('The mock examination has ended')}}},1000);
async function start(){try{
 if(!appToken||!D||!P)throw Error('Missing app session. Please start LabourCodePro.exe again.');
 let incoming={};if(window.AndroidBridge){try{incoming=JSON.parse(AndroidBridge.loadState()||'{}')}catch(e){incoming={}}}else{const r=await fetch('/api/state',{headers:{'X-LCP-Token':appToken}});if(!r.ok)throw Error('Cannot load saved progress');const payload=await r.json();incoming=payload.state||{}}
 state={...defaultState(),...incoming};
 for(const key of ['completed','bookmarks','scores','checkmarks','tasks','studyDays'])if(!Array.isArray(state[key]))state[key]=[];
 if(!state.flashcards||typeof state.flashcards!=='object')state.flashcards={};
 render();
 }catch(e){app.innerHTML=`<div class="boot" style="padding:35px"><h2>Could not open LabourCode Pro</h2><p>${esc(e.message)}</p><p>Reopen the Android application.</p></div>`}
}

/* V4: explanatory, data-driven law architecture and interactive vocabulary. */
const renderInfographicsOriginal = renderInfographics;
renderInfographics = function(){
  const consolidated=[
    {id:'wages',count:4,label:'Wages',tone:'#13a08e',desc:'Wage payment, minimum wages, bonus and equal remuneration'},
    {id:'industrial',count:3,label:'Industrial relations',tone:'#7c6ac9',desc:'Trade unions, industrial disputes and standing orders'},
    {id:'security',count:9,label:'Social security',tone:'#d89a47',desc:'EPF, ESI, maternity, gratuity and other social security laws'},
    {id:'osh',count:13,label:'Workplace safety',tone:'#da7887',desc:'Safety, health and working conditions across work settings'}
  ];
  const terms=['wages','worker','employee','establishment','appropriate government','retrenchment'];
  const glossary=terms.map(t=>D.glossary.find(g=>g.term.toLowerCase()===t)).filter(Boolean);
  return renderInfographicsOriginal()+`<section class="architecture-study"><div class="eyebrow">INTERACTIVE LEGAL ARCHITECTURE</div><h2>From 29 laws to four consolidated Codes</h2><p class="subhead">Select a coloured segment to explore the relevant Code. Counts describe the central laws consolidated, not all state legislation or subordinate Rules.</p><div class="architecture-bar" role="img" aria-label="Former central laws: 4 wages, 3 industrial relations, 9 social security, 13 occupational safety">${consolidated.map(v=>`<button title="${att(v.count+' laws: '+v.desc)}" data-go="module" data-code="${v.id}" style="flex:${v.count};background:${v.tone}"><b>${v.count}</b><small>${esc(v.label)}</small></button>`).join('')}</div><div class="architecture-key">${consolidated.map(v=>`<button data-go="module" data-code="${v.id}"><span class="architecture-dot" style="background:${v.tone}"></span><b>${esc(v.label)}</b><small>${v.count} former Acts</small></button>`).join('')}</div></section>
  <section class="term-network"><div><div class="eyebrow">TAP-TO-EXPLAIN CONCEPT NETWORK</div><h2>Learn the language of employment law</h2><p>Legal definitions can change between Codes and chapters. Tap a concept to read its precise learning note, applicable context and workplace example.</p><div class="term-node-grid">${glossary.map((v,i)=>`<button class="term-node term-node-${i}" data-action="term" data-term="${att(v.term)}"><span class="term-node-icon">${icon(['glossary','learn','compliance','documents','settings','compare'][i])}</span><strong>${esc(v.term)}</strong>${icon('arrow',14)}</button>`).join('')}</div></div><aside class="term-network-visual" aria-hidden="true"><div class="central-orbit">LAW <small>IN CONTEXT</small></div><div class="orb orb-1">01</div><div class="orb orb-2">02</div><div class="orb orb-3">03</div></aside></section>`;
};


// Android native integration: no local server; all core modules operate offline.
if(window.AndroidBridge){
  window.onAndroidDocumentResult = function(result){
    try{const data=JSON.parse(result);if(data.error)throw Error(data.error);view.docResult=data;render();toast('Document screening complete')}catch(e){toast('Document review: '+e.message)}
  };
  window.onAndroidActImported = async function(message){await refreshActStatus(true);render();toast(message||'Document added')};
  const desktopHome=renderHome;
  renderHome=function(){let html=desktopHome();html=html.replace('Offline learning and optional complete Acts','Offline reference and learning').replace('The complete Gazette Acts are not bundled in this source build; they can be bundled at build time or imported into the app.','Original Acts can be embedded in a complete release or added through the device document picker.');return html};
  renderFullActs=function(){const count=Object.keys(ACTS_META).filter(id=>actStatus[id]?.cached).length;return `<div class="eyebrow">ORIGINAL ACTS · NATIVE ANDROID READER</div><h1 class="heading">Full legal text library</h1><p class="subhead">Read the complete Gazette documents inside the Android application, alongside accessible lessons, definitions and workplace case studies.</p><div class="statute-summary"><div class="statute-number"><strong>${count}<span>/4</span></strong><small>Full Acts available offline</small></div><div class="statute-summary-copy"><b>Original legislative documents</b><p>Each complete Code includes its sections and schedules. Documents are stored privately on your phone. The app never silently substitutes its summaries for statutory text.</p></div></div>${count<4?'<div class="banner warn"><b>Original document status</b><p>This Android source package does not contain the four Gazette PDF binaries. For a complete offline release, bundle the authenticated PDFs before building. You can also select authentic PDFs from your phone below. User-provided documents are marked as unverified.</p></div>':''}<div class="law-grid statute-grid">${D.codes.map(c=>{const m=ACTS_META[c.id];return `<article class="law-tile"><div class="law-art"><img src="assets/editorial_${c.id}.webp" alt="${att(c.name)}" loading="lazy"></div><div class="law-content"><div class="law-overline">ACT ${m.act} · ${m.pages} pages</div><h3>${esc(c.name)}</h3><p>${esc(m.note)}</p><div class="law-card-foot">${actFlag(c.id)}<button class="btn secondary" data-go="actreader" data-code="${c.id}">Open reader ${icon('arrow')}</button></div></div></article>`}).join('')}</div><div class="integrity-note" style="margin-top:24px"><b>Legislative accuracy</b><p>Original enactments are not consolidated for later amendments or government rules. Verify the current version and applicable State Rules before relying on a provision professionally.</p></div>`};
  renderActReader=function(){const id=ACTS_META[view.code]?view.code:'wages',m=ACTS_META[id],c=C[id],status=actStatus[id]||{};return `<div class="reader-intro"><button class="btn ghost small" data-go="fullacts">${icon('back')} All Codes</button><div class="reader-name"><div class="eyebrow">COMPLETE ORIGINAL GAZETTE · ${m.act}</div><h1 class="heading">${esc(m.name)}</h1><p class="subhead">${m.pages} original pages · native Android PDF viewer</p></div><div class="reader-actions"><button class="btn secondary" data-go="module" data-code="${id}">Study guide</button></div></div>${status.cached?`<div class="card android-pdf-launch"><div class="eyebrow">OFFLINE PRIMARY SOURCE</div><h2>Every section and schedule — in the app</h2><p>${status.imported?'User-imported text; legal authenticity has not been independently verified.':'Original statutory PDF included with this build.'}</p><p>${Math.round((status.bytes||0)/1024)} KB · ${m.pages} pages</p><button class="btn" data-action="native-open-act" data-code="${id}">Open complete text ${icon('arrow')}</button></div>`:`<div class="card android-pdf-launch"><div class="eyebrow">ORIGINAL TEXT NOT YET AVAILABLE</div><h2>${esc(m.name)}</h2><p>The complete Gazette PDF has not been included in this particular build. The eight lessons below are educational explanations and are not the complete legal text.</p><button class="btn" data-action="import-act" data-code="${id}">Select full Gazette PDF from device ${icon('file')}</button></div>`}${renderReaderAside(id,c,c.cases.slice(0,3))}<div class="disclosure-line">Original enactment text, notifications, rules and amendments are different legal sources. Check current requirements before professional use.</div>`};
  const desktopSettings=renderSettings;
  renderSettings=function(){return desktopSettings().replaceAll('Windows Edition · Portable local application','Android Edition · Offline-first learning').replaceAll('on your Windows','on your Android device').replaceAll('PC’s','phone’s').replaceAll('Exit app','Close application').replaceAll('Directory:</b> <code>%APPDATA%\LabourCodePro\progress.json</code> on typical Windows systems.','Storage:</b> Private application data (Android sandbox).').replaceAll('LabourCode Pro 3.0','LabourCode Pro 1.0')};
  const oldRender=render;
  render=function(){oldRender();const crumb=app.querySelector('.breadcrumb');if(crumb&&window.innerWidth<=920){crumb.innerHTML='<strong>LabourCode Pro</strong><small>Developed by Avinash Ekka</small>'}const old=document.getElementById('android-bottom-nav');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<nav id="android-bottom-nav" class="android-bottom-nav" aria-label="Primary navigation"><button class="${view.route==='home'?'active':''}" data-go="home">${icon('home',20)}<span>Home</span></button><button class="${['fullacts','actreader'].includes(view.route)?'active':''}" data-go="fullacts">${icon('documents',20)}<span>Full Acts</span></button><button class="${['learn','module','lesson','academy'].includes(view.route)?'active':''}" data-go="learn">${icon('learn',20)}<span>Learn</span></button><button class="${['quiz','quizplay'].includes(view.route)?'active':''}" data-go="quiz">${icon('academy',20)}<span>Quiz</span></button><button data-action="android-menu" class="${['visuals','calculator','compliance','advisor','documents','reports','settings','planner'].includes(view.route)?'active':''}">${icon('filter',20)}<span>More</span></button></nav>`)};
  document.body.addEventListener('click',ev=>{const el=ev.target.closest('#android-bottom-nav [data-go],#android-bottom-nav [data-action]');if(!el)return;if(el.dataset.go)go(el.dataset.go);else if(el.dataset.action==='android-menu'){popup('Explore LabourCode Pro',`<div class="android-menu-grid">${NAV.flatMap(g=>g.items).filter(([id])=>!['home','learn','quiz','fullacts'].includes(id)).filter((x,i,a)=>a.findIndex(z=>z[0]===x[0])===i).map(([id,title,ico])=>`<button class="btn secondary" data-go="${id}" onclick="document.getElementById('modal-root').innerHTML='';go('${id}')">${icon(ico,19)} ${esc(title)}</button>`).join('')}</div>`)}},false);
  app.addEventListener('click',e=>{const el=e.target.closest('[data-action="native-open-act"]');if(el){e.stopImmediatePropagation();AndroidBridge.openAct(el.dataset.code)}},true);
  refreshActStatus(true);
}
